comms.text:
@1 וַאֲמַר יְיָ לְמשֶׁה עוּל לְוָת פַּרְעֹה אֲרֵי אֲנָא יַקָרִית יָת לִבֵּהּ וְיָת לִבָּא דְעַבְדוֹהִי בְּדִיל לְשַׁוָאָה אָתַי אִלֵין בֵּינֵיהוֹן:
@2 וּבְדִיל דְתִשְׁתָּעֵי קֳדָם בְּרָךְ וּבַר בְּרָךְ יָת נִסִין דִי עֲבָדִית בְּמִצְרַיִם וְיָת אַתְוָתַי דִי שַׁוֵיתִי בְהוֹן וְתִדְעוּן אֲרֵי אֲנָא יְיָ:
@3 וַאֲתָא משֶׁה וְאַהֲרֹן לְוָת פַּרְעֹה וַאֲמָרוּ לֵהּ כִּדְנַן אֲמַר יְיָ אֱלָהָא דִיהוּדָאֵי עַד אִמָתַי מְסָרֵב אַתְּ לְאִתְכְּנָעָא מִן קֳדָמָי שַׁלַח עַמִי וְיִפְלְחוּן קֳדָמָי:
@4 אֲרֵי אִם סָרֵיב אַתְּ לְשַׁלָחָא יָת עַמִי הָא אֲנָא מַיְיתִי מְחָר גוֹבָא בִּתְחוּמָךְ:
@5 וַחֲפָא יָת עֵין שִׁמְשָׁא דְאַרְעָא וְלָא יִכּוּל לְמֶחֱזֵי יָת אַרְעָא וְיֵכוּל יָת שְׁאָר שֵׁזַבְתָּא דְאִשְׁתָּאַר לְכוֹן מִן בַּרְדָא וְיֵכוּל יָת כָּל אִילָנָא דְאַצְמַח לְכוֹן מִן חַקְלָא:
@6 וְיִמְלוּן בָּתָּיךְ וּבָתֵּי כָל עַבְדָיךְ וּבָתֵּי כָל מִצְרַיִם דִי לָא חֲזוֹ אֲבָהָתָךְ וַאֲבָהַת אֲבָהָתָךְ מִיוֹמָא דְמֶהֱוֵיהוֹן עַל אַרְעָא עַד יוֹמָא הָדֵין וְאִתְפְּנִי וּנְפַק מִן קֳדָם פַּרְעֹה:
@7 וַאֲמָרוּ עַבְדֵי פַרְעֹה לֵהּ עַד אִמָתַי יְהֵי דֵין לָנָא לְתַקְלָא שַׁלַח יָת גֻבְרַיָא וְיִפְלְחוּן קֳדָם יְיָ אֱלָהֲהוֹן הַעַד כְּעַן לָא יְדַעְתָּ אֲרֵי אֲבֵדַת מִצְרָיִם:
@8 וְאִתּוֹתַב יָת משֶׁה וְיָת אַהֲרֹן לְוָת פַּרְעֹה וַאֲמַר לְהוֹן אֱזִילוּ פְלָחוּ קֳדָם יְיָ אֱלָהֲכוֹן מָן וּמָן דְאָזְלִין:
@9 וַאֲמַר משֶׁה בְּעוּלֵמָנָּא וּבְסָבָנָּא נֵזֵיל בְּבָנָנָא וּבִבְנָתָנָא בְּעָנָנָא וּבְתוֹרָנָא נֵזֵיל אֲרֵי חַגָא קֳדָם יְיָ לָנָא:
@10 וַאֲמַר לְהוֹן יְהֵי כֵן מֵימְרָא דַיְיָ בְּסַעְדְכוֹן כַּד אֲשַּׁלַח יָתְכוֹן וְיָת טַפְלְכוֹן חֲזוֹ אֲרֵי בִישָׁא דְאַתּוּן סְבִירִין לְמֶעְבַּד לָקֳבֵל אַפֵּיכוֹן לְאִסְתַּחָרָא:
@11 לָא כֵן אֱזִילוּ כְעַן גֻבְרַיָא וּפְלָחוּ קֳדָם יְיָ אֲרֵי יָתַהּ אַתּוּן בָּעָן וְתָרִיךְ יָתְהוֹן מִן קֳדָם פַּרְעֹה:
@12 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יְדָךְ עַל אַרְעָא דְמִצְרָיִם וְיֵתֵי גוֹבָא וְיִסַק עַל אַרְעָא דְמִצְרָיִם וְיֵכוּל יָת כָּל עִסְבָּא דְאַרְעָא יָת כָּל דִי אַשְׁאַר בַּרְדָא:
@13 וַאֲרֵים משֶׁה יָת חֻטְרֵהּ עַל אַרְעָא דְמִצְרַיִם וַיְיָ דַבַּר רוּחַ קִדוּמָא בְּאַרְעָא כָּל יוֹמָא הַהוּא וְכָל לֵילְיָא צַפְרָא הֲוָה וְרוּחַ קִדוּמָא נְטַּל יָת גוֹבָא:
@14 וּסְלֵיק גוֹבָא עַל כָּל אַרְעָא דְמִצְרַיִם וּשְׁרָא בְּכָל תְּחוּם מִצְרָיִם תַּקִיף לַחֲדָא קֳדָמוֹהִי לָא הֲוָה כֵן גוֹבָא דִכְוָתֵהּ וּבַתְרוֹהִי לָא יְהֵי כֵן:
@15 וַחֲפָא יָת עֵין שִׁמְשָׁא דְכָל אַרְעָא וַחֲשׁוֹכַת אַרְעָא וַאֲכַל יָת כָּל עֶסְבָּא דְאַרְעָא וְיָת כָּל פֵּירֵי אִילָנָא דִי אַשְׁאַר בַּרְדָא וְלָא אִשְׁתָּאַר כָּל יָרוֹקָא בְּאִילָנָא וּבְעֶסְבָּא דְחַקְלָא בְּכָל אַרְעָא דְמִצְרָיִם:
@16 וְאוֹחִי פַרְעֹה לְמִקְרֵי לְמשֶׁה וּלְאַהֲרֹן וַאֲמַר חָבִית קֳדָם יְיָ אֱלָהֲכוֹן וּלְכוֹן:
@17 וּכְעַן שְׁבוֹק כְּעַן לְחוֹבִי בְּרַם זִמְנָא הָדָא וְצַלוֹ קָדָם יְיָ אֱלָהֲכוֹן וְיַעְדֵי מִנִי לְחוֹד יָת מוֹתָא הָדֵין:
@18 וּנְפַק מִלְוָת פַּרְעֹה וְצַלִי קֳדָם יְיָ:
@19 וַהֲפַךְ יְיָ רוּחָא מַעַרְבָא תַּקִיף לַחֲדָא וּנְטַל יָת גוֹבָא וּרְמָהִי לְיַמָא דְסוּף לָא אִשְׁתָּאַר גוֹבָא חַד בְּכֹל תְּחוּם מִצְרָיִם:
@20 וְאַתְקֵף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת בְּנֵי יִשְׂרָאֵל:
@21 וַאֲמַר יְיָ לְמשֶׁה אֲרֵים יְדָךְ עַל צֵית שְׁמַיָא וִיהֵי חֲשׁוֹכָא עַל אַרְעָא דְמִצְרָיִם בָּתַר דְיַעְדֵי קְבֵל לֵילְיָא:
@22 וַאֲרֵים משֶׁה יָת יְדֵהּ עַל צֵית שְׁמַיָא וַהֲוָה חֲשׁוֹךְ קְבֵל בְּכָל אַרְעָא דְמִצְרַיִם תְּלָתָא יוֹמִין:
@23 לָא חֲזוֹ אֱנָשׁ יָת אֲחוֹהִי וְלָא קָמוּ אֱנָשׁ מִתְּחוֹתוֹהִי תְּלָתָא יוֹמִין וּלְכָל בְּנֵי יִשְׂרָאֵל הֲוָה נְהוֹרָא בְּמוֹתְבָנְהוֹן:
@24 וּקְרָא פַרְעֹה לְמשֶׁה וַאֲמַר אֱזִילוּ פְּלָחוּ קֳדָם יְיָ לְחוֹד עָנְכוֹן וְתוֹרְכוֹן שְׁבוּקוּ אַף טַפְלְכוֹן יֵזֵיל עִמְכוֹן:
@25 וַאֲמַר משֶׁה אַף אַתְּ תִּמְסַר בִּידָנָא נִכְסַת קֻדְשִׁין וַעֲלָוָן וְנַעְבֵּד קֳדָם יְיָ אֱלָהָנָא:
@26 וְאַף בְּעִירָנָא יֵזֵיל עִמָנָא לָא תִשְׁתָּאַר מִדַעַם אֲרֵי מִנֵהּ אֲנַחְנָא נָסְבִין לְמִפְלַח קֳדָם יְיָ אֱלָהָנָא וַאֲנַחְנָא לֵית אֲנַחְנָא יָדְעִין מָה נִפְלַח קֳדָם יְיָ עַד מֵיתָנָא תַּמָן:
@27 וְאַתְקֵיף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא אָבָה לְשַׁלָחוּתְהוֹן:
@28 וַאֲמַר לֵּהּ פַּרְעֹה אִזֵיל מֵעִלָוָי אִסְתַּמַר לָךְ לָא תוֹסִיף לְמֶחֱזֵי אַפַּי אֲרֵי בְּיוֹמָא דְתֶחֱזֵי אַפַּי תְּמוּת:
@29 וַאֲמַר משֶׁה יָאוּת מַלֵילְתָּא לָא אוֹסִיף עוֹד לְמֶחֱזֵי אַפָּיךְ:
@30 וַאֲמַר יְיָ לְמשֶׁה עוֹד מַכְתַּשׁ חַד אַיְתִי עַל פַּרְעֹה וְעַל מִצְרַיִם בָּתַר כֵּן יְשַׁלַח יָתְכוֹן מִכָּא כְּשַׁלָחוּתֵהּ גְמֵירָא תָּרָכָא יְתָרֵךְ יָתְכוֹן מִכָּא:
@31 מַלֵיל כְּעַן קֳדָם עַמָא וּשְׁאִילוּ גְבַר מִן חַבְרֵהּ וְאִתְּתָא מִן חַבְרָתַהּ מָנִין דִכְסַף וּמָנִין דִדְהָב:
@32 וִיהַב יְיָ יָת עַמָא לְרַחֲמִין בְּעֵינֵי מִצְרָיִם אַף גַבְרָא משֶׁה רַב לַחֲדָא בְּאַרְעָא דְמִצְרַיִם בְּעֵינֵי עַבְדֵי פַרְעֹה וּבְעֵינֵי עַמָא:
@33 וַאֲמַר משֶׁה כִּדְנַן אֲמַר יְיָ כְּפַלְגוּת לֵילְיָא אֲנָא מִתְגְלִי בְּגוֹ מִצְרָיִם:
@34 וִימוּת כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבּוּכְרָא דְפַרְעֹה דְעָתִיד לְמִתַּב עַל כָּרְסֵי מַלְכוּתֵהּ עַד בּוּכְרָא דְאַמְתָא דִי בָּתַר רֵיחְיָא וְכֹל בּוּכְרָא דִבְעִירָא:
@35 וּתְהֵי צְוַחְתָּא רַבָּא בְּכָל אַרְעָא דְמִצְרָיִם דִכְוָתֵהּ לָא הֲוַת וְדִכְוָתֵהּ לָא תוֹסֵף:
@36 וּלְכֹל בְּנֵי יִשְׂרָאֵל לָא יַנְזֵק כַּלְבָּא בְּלִישְׁנֵהּ לְמִנְבַּח לְמֵאֲנָשָׁא וְעַד בְּעִירָא בְּדִיל דְתִדְעוּן דְיַפְרֵישׁ יְיָ בֵּין מִצְרַיִם וּבֵין יִשְׂרָאֵל:
@37 וְיֶחֱתוּן כָּל עַבְדָיךְ אִלֵין לְוָתִי וְיִבְעוֹן מִנִי לְמֵימָר פּוּק אַתְּ וְכָל עַמָא דִי עִמָךְ וּבָתַר כֵּן אֶפּוֹק וּנְפַק מִלְוָת פַּרְעֹה בִּתְקוֹף רְגָז:
@38 וַאֲמַר יְיָ לְמשֶׁה לָא יְקַבֵּל מִנְכוֹן פַּרְעֹה בְּדִיל לְאַסְגָאָה מוֹפְתַי בְּאַרְעָא דְמִצְרָיִם:
@39 וּמשֶׁה וְאַהֲרֹן עֲבָדוּ יָת כָּל מוֹפְתַיָא הָאִלֵין קֳדָם פַּרְעֹה וְתַקַף יְיָ יָת לִבָּא דְפַרְעֹה וְלָא שַׁלַח יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעֵהּ:
@40 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן בְּאַרְעָא דְמִצְרַיִם לְמֵימָר:
@41 יַרְחָא הָדֵין לְכוֹן רֵישׁ יַרְחִין קַדְמַאי הוּא לְכוֹן לְיַרְחֵי שַׁתָּא:
@42 מַלִילוּ עִם כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל לְמֵימַר בְּעַסְרָא לְיַרְחָא הָדֵין וְיִסְבוּן לְהוֹן גְבַר אִמָר לְבֵית אַבָּא אִמָר לְבֵיתָא:
@43 וְאִם יִזְעֵיר בֵּיתָא מִלְאִתְמְנָאָה עַל אִמְרָא וְיִסַב הוּא וְשֵׁיבָבֵהּ דְקָרִיב לְבֵיתֵהּ בְּמִנְיַן נַפְשָׁתָא גְבַר לְפוּם מֵיכְלֵהּ תִּתְמְנוּן עַל אִמְרָא:
@44 אִמַר שְׁלִים דְכַר בַּר שַׁתֵּהּ יְהֵי לְכוֹן מִן אִמְרַיָא וּמִן עִזַיָא תִּסְבוּן:
@45 וִיהֵי לְכוֹן לְמַטְרָא עַד אַרְבְּעָא עַסְרָא יוֹמָא לְיַרְחָא הָדֵין וְיִכְּסוּן יָתֵהּ כֹּל קְהָלָא כְנִשְׁתָּא דְיִשְׂרָאֵל בֵּין שִׁמְשַּׁיָא:
@46 וְיִסְבוּן מִן דְמָא וְיִתְּנוּן עַל תְּרֵין סִפַּיָא וְעַל שַׁקְפָא עַל בָּתַּיָא דְיֵכְלוּן יָתֵהּ בְּהוֹן:
@47 וְיֵכְלוּן יָת בִּסְרָא בְּלֵילָא הַהוּא טְּוֵי נוּר וּפַטִיר עַל מְרָרִין יֵכְלֻנֵהּ:
@48 לָא תֵיכְלוּן מִנֵהּ כַּד חַי וְאַף לָא בַשָׁלָא מְבֻשָׁל בְּמַיָא אֱלָהֵן טְוֵי נוּר רֵישֵׁיה עַל כְּרָעוֹהִי וְעַל גַוֵהּ:
@49 וְלָא תַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא וּדְיִשְׁתָּאַר מִנֵהּ עַד צַפְרָא בְּנוּרָא תוֹקְדוּן:
@50 וּכְדֵין תֵּיכְלוּן יָתֵהּ חַרְצֵיכוֹן יְהוֹן אֲסִירִין מְסָנֵיכוֹן בְּרִגְלֵיכוֹן וְחוּטְרֵיכוֹן בִּידֵיכוֹן וְתֵיכְלוּן יָתֵהּ בִּבְהִילוּ פִּסְחָא הוּא קֳדָם יְיָ:
@51 וְאִתְגְלֵיתִי בְאַרְעָא דְמִצְרַיִם בְּלֵילְיָא הָדֵין וְאֶקְטוֹל כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מֵאֲנָשָׁא וְעַד בְּעִירָא וּבְכָל טַעֲוַת מִצְרַיִם אַעְבֵּד דִינִין אֲנָא יְיָ:
@52 וִיהֵי דְמָא לְכוֹן לְאָת עַל בָּתַּיָא דִי אַתּוּן תַּמָן וְאֶחֱזֵי יָת דְמָא וְאֵיחוֹס עֲלֵיכוֹן וְלָא יְהֵי בְכוֹן מוֹתָא לְחַבָּלָא בְּמִקְטְלִי בְּאַרְעָא דְמִצְרָיִם:
@53 וִיהֵי יוֹמָא הָדֵין לְכוֹן לְדוּכְרָנָא וּתְחַגוּן יָתֵהּ חַגָא קָדָם יְיָ לְדָרֵיכוֹן קְיָם עָלָם תְּחַגֻנֵהּ:
@54 שִׁבְעַת יוֹמִין פַּטִיר תֵּיכְלוּן בְּרַם בְּיוֹמָא קַדְמָאָה תְּבַטְלוּן חֲמִיעַ מִבָּתֵּיכוֹן אֲרֵי כָּל דְיֵכוּל חֲמִיעַ וְיִשְׁתֵּצֵי אֱנָשָׁא הַהוּא מִיִשְׂרָאֵל מִיוֹמָא קַדְמָאָה עַד יוֹמָא שְׁבִיעָאָה:
@55 וּבְיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ וּבְיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִיבִידָא לָא יִתְעֲבֵד בְּהוֹן בְּרַם דִי מִתְאֲכֵל לְכָל נְפַשׁ הוּא בִלְחוֹדוֹהִי יִתְעֲבֵד לְכוֹן:
@56 וְתִטְרוּן יָת פַּטִירָא אֲרֵי בִּכְרַן יוֹמָא הָדֵין אַפֵּיקִית יָת חֵילֵיכוֹן מֵאַרְעָא דְמִצְרָיִם וְתִטְּרוּן יָת יוֹמָא הָדֵין לְדָרֵיכוֹן קְיָם עָלָם:
@57 בְּנִיסָן בְּאַרְבְּעָא עַסְרָא יוֹמָא לְיַרְחָא בְּרַמְשָׁא תֵּיכְלוּן פַּטִירָא עַד יוֹמָא עֶסְרִין וְחַד לְיַרְחָא בְּרַמְשָׁא:
@58 שִׁבְעַת יוֹמִין חֲמִיר לָא יִשְׁתְּכַח בְּבָתֵּיכוֹן אֲרֵי כָּל דְיֵכוּל מַחְמְעָא וְיִשְׁתֵּצֵי אֱנָשָׁא הַהוּא מִכְּנִשְׁתָּא דְיִשְׂרָאֵל בְּגִיוֹרָא וּבְיַצִיבָא דְאַרְעָא:
@59 כָּל מַחְמְעָא לָא תֵיכְלוּן בְּכֹל מוֹתְבָנֵיכוֹן תֵּיכְלוּן פַּטִירָא:
@60 וּקְרָא משֶׁה לְכָל סָבֵי יִשְׂרָאֵל וַאֲמַר לְהוֹן אִתְנְגִידוּ וְסִיבוּ לְכוֹן (מִן בְּנֵי) עָנָא לְזַרְעֲיָתְכוֹן וְכוּסוּ פִסְחָא:
@61 וְתִסְבּוּן אֱסָרַת אֵזוֹבָא וְתִטְבְּלוּן בִּדְמָא דִבְמָנָא וְתַדוּן לְשַׁקְפָא וְלִתְרֵין סִפַּיָא מִן דְמָא דִבְמָנָא וְאַתּוּן לָא תִפְּקוּן אֱנַשׁ מִתְּרַע בֵּיתֵהּ עַד צַפְרָא:
@62 וְיִתְגְלֵי יְיָ לְמִמְחֵי יָת מִצְרַיִם וְיֶחֱזֵי יָת דְמָא עַל שַׁקְפָא וְעַל תְּרֵין סִפַּיָא וְיֵחוֹס יְיָ עַל תַּרְעָא וְלָא יִשְׁבּוֹק לְחַבָּלָא לְמֵיעַל לְבָתֵּיכוֹן לְמִמְחֵי:
@63 וְתִטְרוּן יָת פִּתְגָמָא הָדֵין לִקְיָם לָךְ וְלִבְנָיךְ עַד עָלָם:
@64 וִיהֵי אֲרֵי תֵעֲלוּן לְאַרְעָא דְיִתֵּן יְיָ לְכוֹן כְּמָא דִי מַלִיל וְתִטְּרוּן יָת פָּלְחָנָא הָדֵין:
@65 וִיהֵי אֲרֵי יֵימְרוּן לְכוֹן בְּנֵיכוֹן מָא פָּלְחָנָא הָדֵין לְכוֹן:
@66 וְתֵימְרוּן דַבַּח חֲיָס הוּא קֳדָם יְיָ דִי חָס עַל בָּתֵּי בְנֵי יִשְׂרָאֵל בְּמִצְרַיִם כַּד הֲוָה מָחֵי יָת מִצְרָאֵי וְיָת בָּתָּנָא שֵׁזִיב וּכְרַע עַמָא וּסְגִידוּ:
@67 וַאֲזָלוּ וַעֲבָדוּ בְּנֵי יִשְׂרָאֵל כְּמָא דְפַקִיד יְיָ יָת משֶׁה וְאַהֲרֹן כֵּן עֲבָדוּ:
@68 וַהֲוָה בְּפַלְגוּת לֵילְיָא וַיְיָ קְטַל כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבּוּכְרָא דְפַרְעֹה דְעָתִיד לְמִתַּב עַל כָּרְסֵי מַלְכוּתֵהּ עַד בּוּכְרָא דְשִׁבְיָא דִי בְּבֵית אֲסִירֵי וְכֹל בּוּכְרָא דִבְעִירָא:
@69 וְקָם פַּרְעֹה לֵילְיָא הוּא וְכָל עַבְדוֹהִי וְכָל מִצְרַיִם וַהֲוַת צְוַחְתָּא רַבְּתָא בְּמִצְרָיִם אֲרֵי לֵית בֵּיתָא דִי לֵית הֲוָה בֵהּ תַּמָן מֵתָא:
@70 וּקְרָא לְמשֶׁה וּלְאַהֲרֹן לֵילְיָא וַאֲמַר קוּמוּ פּוּקוּ מִגוֹ עַמִי אַף אַתּוּן אַף בְּנֵי יִשְׂרָאֵל וֶאֱזִילוּ פְלָחוּ קֳדָם יְיָ כְּמָא דִהֲוֵתוּן אָמְרִין:
@71 אַף עַנְכוֹן אַף תּוֹרְכוֹן דְבָרוּ כְּמָא דִי מַלֵלְתֻּן וֶאֱזִילוּ וְצַלוֹ אַף עָלָי:
@72 וּתְקֵיפַת מִצְרַיִם עַל עַמָא לְאוֹחָאָה לְשַׁלָחוּתְהוֹן מִן אַרְעָא אֲרֵי אֲמָרוּ כֻּלָנָא מָיְתִין:
@73 וּנְטַל עַמָא יָת לַיְשֵׁיהוֹן עַד לָא חֲמָע מוֹתַר אַצְוָתְהוֹן צְרִיר בִּלְבָשֵׁהוֹן עַל כַּתְפֵּיהוֹן:
@74 וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּפִתְגָמָא דְמשֶׁה וּשְׁאִילוּ מִמִצְרַיִם מָנִין דִכְסַף וּמָנִין דִדְהַב וּלְבוּשִׁין:
@75 וַייָ יְהַב יָת עַמָא לְרַחֲמִין בְּעֵינֵי מִצְרַיִם וּשְׁאֵילִנוּן וְרוֹקִינוּ יָת מִצְרַיִם:
@76 וּנְטָלוּ בְנֵי יִשְׂרָאֵל מֵרַעְמְסֵס לְסֻכּוֹת כְּשִׁתְּ מֵאָה אַלְפִין רִגְלָאִין גֻבְרַיָא בַּר מִטַפְלָא:
@77 וְאַף נוּכְרָאִין סַגִיאִין סְלִיקוּ עִמְהוֹן וְעָנָא וְתוֹרִין בְּעִירָא סַגִי לַחֲדָא:
@78 וַאֲפוֹ יָת לַיְשָׁא דִי אַפִּיקוּ מִמִצְרַיִם גְרִיצָן פַּטִירָן אֲרֵי לָא חֲמָע אֲרֵי אִתָּרָכוּ מִמִצְרַיִם וְלָא יָכִילוּ לְאִתְעַכָּבָא וְאַף זְוָדִין לָא עֲבָדוּ לְהוֹן:
@79 וּמוֹתַב בְּנֵי יִשְׂרָאֵל דִי יְתִיבוּ בְּמִצְרָיִם אַרְבַּע מְאָה וּתְלָתִין שְׁנִין:
@80 וַהֲוָה מִסוֹף אַרְבַּע מְאָה וּתְלָתִין שְׁנִין וַהֲוָה בִּכְרַן יוֹמָא הָדֵין נְפָקוּ כָּל חֵילַיָא דַיְיָ מֵאַרְעָא דְמִצְרָיִם:
@81 לֵילֵי נְטִּיר הוּא קֳדָם יְיָ לְאַפָּקוּתְהוֹן מֵאַרְעָא דְמִצְרַיִם הוּא לֵילְיָא הָדֵין קֳדָם יְיָ נְטִירִין לְכָל בְּנֵי יִשְׂרָאֵל לְדָרֵיהוֹן:
@82 וַאֲמַר יְיָ לְמשֶׁה וּלְאַהֲרֹן דָא גְזֵירַת פִּסְחָא כָּל בַּר יִשְׂרָאֵל דְיִשְׁתַּמַד לָא יֵכוּל בֵּהּ:
@83 וְכָל עָבֵד גְבַר זְבִינֵי כַסְפָּא וְתִגְזַר יָתֵהּ בְּכֵן יֵכוּל בֵּהּ:
@84 תּוֹתָבָא וַאֲגִירָא לָא יֵכוּל בֵּהּ:
@85 בַּחֲבוּרָא חֲדָא יִתְאָכֵל לָא תַפֵּיק מִן בֵּיתָא מִן בִּסְרָא לְבָרָא וְגַרְמָא לָא תִתְבְּרוּן בֵּהּ:
@86 כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל יַעְבְדוּן יָתֵהּ:
@87 וַאֲרֵי יִתְגַיַר עִמָךְ גִיוֹרָא וְיַעְבֵּד פִּסְחָא קֳדָם יְיָ מִגְזַר לֵהּ כָּל דְכוּרָא וּבְכֵן יִקְרַב לְמֶעְבְּדֵהּ וִיהֵי כְּיַצִיבָא דְאַרְעָא וְכָל עַרְלָא לָא יֵכוּל בֵּהּ:
@88 אוֹרַיְתָא חֲדָא יְהֵא לְיַצִיבָא וּלְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@89 וַעֲבָדוּ כָּל בְּנֵי יִשְׂרָאֵל כְּמָא דִי פַקִיד יְיָ יָת משֶׁה וְיָת אַהֲרֹן כֵּן עֲבָדוּ:
@90 וַהֲוָה בִּכְרַן יוֹמָא הָדֵין אַפֵּיק יְיָ יָת בְּנֵי יִשְׂרָאֵל מֵאַרְעָא דְמִצְרַיִם עַל חֵילֵיהוֹן:
@91 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@92 אַקְדֵשׁ קֳדָמַי כָּל בּוּכְרָא פָּתַח כָּל וַלְדָא בִּבְנֵי יִשְׂרָאֵל בֶּאֱנָשָׁא וּבִבְעִירָא דִילִי הוּא:
@93 וַאֲמַר משֶׁה לְעַמָא הֲווֹ דְכִירִין יָת יוֹמָא הָדֵין דִי נְפַקְתּוּן מִמִצְרַיִם מִבֵּית עַבְדוּתָא אֲרֵי בִּתְקוֹף יְדָא אַפֵּיק יְיָ יָתְכוֹן מִכָּא וְלָא יִתְאֲכֵל חֲמִיעַ:
@94 יוֹמָא דֵין אַתּוּן נָפְקִין בְּיַרְחָא דְאַבִּיבָא:
@95 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ לְאַרְעָא דִכְנַעֲנָאֵי וְחִתָּאֵי וֶאֱמוֹרָאֵי וְחִוָאֵי וִיבוּסָאֵי דִי קַיִים לַאֲבָהָתָךְ לְמִתַּן לָךְ אַרְעָא עַבְדָא חֲלָב וּדְבָשׁ וְתִפְלַח יָת פָּלְחָנָא הָדָא בְּיַרְחָא הָדֵין:
@96 שִׁבְעָה יוֹמִין תֵּיכוּל פַּטִירָא וּבְיוֹמָא שְׁבִיעָאָה חַגָא קֳדָם יְיָ:
@97 פַּטִיר יִתְאֲכֵל יָת שִׁבְעַת יוֹמִין וְלָא יִתְחֲזֵי לָךְ חֲמִיעַ וְלָא יִתְחֲזֵי לָךְ חֲמִיר בְּכָל תְּחוּמָךְ:
@98 וּתְחַוֵי לִבְנָךְ בְּיוֹמָא הַהוּא לְמֵימָר בְּדִיל דֵין עֲבַד יְיָ לִי בְּמִפְּקִי מִמִצְרָיִם:
@99 וִיהֵי לָךְ לְאָת עַל יְדָךְ וּלְדָכְרָנָא בֵּין עֵינָיךְ בְּדִיל תְּהֵי אוֹרַיְתָא דַיְיָ בְּפוּמָךְ אֲרֵי בִּידָא תַקִיפָא אַפְּקָךְ יְיָ מִמִצְרָיִם:
@100 וְתִטַּר יָת קְיָמָא הָדָא לְזִמְנַהּ מִזְמַן לִזְמָן:
@101 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ לְאַרְעָא דִכְנַעֲנָאֵי כְּמָא דִי קַיִים לָךְ וְלַאֲבָהָתָךְ וְיִתְּנִנַהּ לָךְ:
@102 וְתַעְבַּר כָּל פָּתַח וַלְדָא קֳדָם יְיָ וְכָל פָּתַח וְלַד בְּעִירָא דִי יְהֵי לָךְ דִכְרִין תַּקְדֵשׁ קֳדָם יְיָ:
@103 וְכָל פָּתַח (בּוּכְרָא) דַחֲמָרָא תִּפְרוֹק בְּאִמְרָא וְאִם לָא תִפְרוֹק וְתִנְקְפֵהּ וְכָל בּוּכְרָא דַאֲנָשָׁא בִּבְנָיךְ תִּפְרוֹק:
@104 וִיהֵי אֲרֵי יִשְׁאֲלִנָךְ בְּנָךְ מְחָר לְמֵימַר מָא דָא וְתֵימַר לֵהּ בִּתְקוֹף יְדָא אַפְּקָנָא יְיָ מִמִצְרַיִם מִבֵּית עַבְדוּתָא:
@105 וַהֲוָה אֲרֵי אַקְשֵׁי פַרְעֹה לְשַׁלָחוּתָנָא וּקְטַל יְיָ כָּל בּוּכְרָא בְּאַרְעָא דְמִצְרַיִם מִבּוּכְרָא דַאֲנָשָׁא וְעַד בּוּכְרָא דִבְעִירָא עַל כֵּן אֲנָא דָבַח קֳדָם יְיָ כָּל פָּתַח וַלְדָא דִכְרִין וְכָל בּוּכְרָא דִבְנַי אֶפְרוֹק:
@106 וִיהֵי לְאָת עַל יְדָךְ וְלִתְפִלִין בֵּין עֵינָיךְ אֲרֵי בִּתְקוֹף יְדָא אַפְּקָנָא יְיָ מִמִצְרָיִם: ססס:

@1 **ויאמר ה' אל משה בא אל פרעה.** והתרה בו: **שתי.** שימי, שאשית אני:
@2 **ולמען תספר.** בתורה להודיע לדורות: **התעללתי.** שחקתי, כמו (במדבר כב כט) כי התעללת בי, (שמואל א' ו ו) הלוא כאשר התעולל בהם, האמור במצרים. ואינו לשון פועל ומעללים, שאם כן היה לו לכתוב עוללתי, כמו (איכה א כב) ועולל למו כאשר עוללת לי, (שם כב) אשר עולל לי:
@3 **לענת.** כתרגומו לאתכנעא, והוא מגזרת עני, מאנת להיות עני ושפל מפני:
@5 **את עין הארץ.** את מראה הארץ: **ולא יוכל** וגו' **.** הרואה לראות את הארץ, ולשון קצרה דבר:
@7 **הטרם תדע.** העוד לא ידעת כי אבדה מצרים:
@8 **ויושב.** הושבו על ידי שליח ששלחו אחריהם והשיבום אל פרעה:
@10 **כאשר אשלח אתכם ואת טפכם.** אף כי אשלח גם את הצאן ואת הבקר כאשר אמרתם: **ראו כי רעה נגד פניכם.** כתרגומו. ומדרש אגדה שמעתי כוכב אחד יש ששמו רעה. אמר להם פרעה רואה אני באיצטגנינות שלי אותו כוכב עולה לקראתכם במדבר, והוא סימן דם והריגה וכשחטאו ישראל בעגל ובקש הקדוש ברוך הוא להרגם אמר משה בתפלתו (שמות לב יב) למה יאמרו מצרים לאמר ברעה הוציאם, זו היא שאמר להם ראו כי רעה נגד פניכם, מיד (שם יד) וינחם ה' על הרעה והפך את הדם לדם מילה, שמל יהושע אותם, וזהו שנאמר (יהושע ה ט) היום גלותי את חרפת מצרים מעליכם שהיו אומרים לכם דם אנו רואין עליכם במדבר:
@11 **לא כן.** כאשר אמרתם להוליך הטף עמכם אלא לכו נא הגברים ועבדו את ה': **כי אתה אתם מבקשים.** כי אותה בקשתם עד הנה (שמות ה ח) נזבחה לאלהינו, ואין דרך הטף לזבוח: **ויגרש אתם.** הרי זה לשון קצר ולא פרש מי המגרש:
@12 **בארבה.** בשביל מכת הארבה:
@13 **ורוח הקדים.** רוח מזרחית נשא את הארבה, לפי שבא כנגדו שמצרים בדרומית מערבית היתה, כמו שמפורש במקום אחר:
@14 **ואחריו לא יהיה כן.** ואותו שהיה בימי יואל, שנאמר (יואל ב ב) כמוהו לא נהיה מן העולם, למדנו שהיה כבד משל משה כי אותו של יואל היה על ידי מינין הרבה, שהיו יחד ארבה ילק חסיל גזם, אבל של משה לא היה אלא של מין אחד, וכמוהו לא היה ולא יהיה:
@15 **כל ירק.** עלה ירוק וירדור''א בלעז :
@19 **רוח ים.** רוח מערבי: **ימה סוף.** אומר אני שים סוף היה מקצתו במערב כנגד כל רוח דרומית וגם במזרח של ארץ ישראל, לפיכך רוח ים תקעו לארבה בימה סוף כנגדו. וכן מצינו לענין תחומין שהוא פונה לצד מזרח, שנאמר (שמות כג לא) מים סוף ועד ים פלשתים, ממזרח למערב, שים פלשתים במערב היה, שנאמר בפלשתים (צפניה ב ה) יושבי חבל הים גוי כרתים: **לא נשאר ארבה אחד.** אף המלוחים שמלחו מהם:
@21 **וימש חשך.** ויחשיך עליהם חשך יותר מחשכו של לילה, וחשך של לילה יאמיש ויחשיך עוד: **וימש.** כמו ויאמש יש לנו תיבות הרבה חסרות אל''ף לפי שאין הברת האל''ף נכרת כל כך אין הכתוב מקפיד על חסרונה, כגון (ישע' יג כ) ולא יהל שם ערבי, כמו לא יאהל, לא יטה אהלו. וכן (שמואל ב כב מ) ותזרני חיל, כמו ותאזרני. ואונקלוס תרגם לשון הסרה, כמו (שמות יג כב) לא ימיש בתר דיעדי קבל ליליא, כשיגיע סמוך לאור היום. אבל אין הדבר מישב על הוי''ו של וימש, לפי שהוא כתוב אחר ויהי חשך. ומדרש אגדה פותרו לשון (דברים כח כט) ממשש בצהרים, שהיה כפול ומכפל ועב עד שהיה בו ממש:
@22 **ויהי חשך אפלה** וכו' **שלשת ימים** וגו' **.** חשך של אופל שלא ראו איש את אחיו אותן שלשת ימים. ועוד שלשת ימים אחרים חשך מכפל על זה, שלא קמו איש מתחתיו. יושב אין יכול לעמוד, ועומד אין יכול לישב. ולמה הביא עליהם חשך, שהיו בישראל באותו הדור רשעים, ולא היו רוצים לצאת, ומתו בשלשת ימי אפלה כדי שלא יראו מצרים במפלתם ויאמרו אף הן לוקין כמונו. ועוד שחפשו ישראל וראו את כליהם, וכשיצאו והיו שואלין מהן והיו אומרים אין בידינו כלום אמר לו אני ראיתיו בביתך ובמקום פלוני הוא: **שלשת ימים.** שלוש של ימים טירציינ''א בלעז וכן שבעת ימים בכל מקום שטיינ''א של ימים. כד **יצג.** יהא מצג במקומו:
@25 **גם אתה תתן.** לא דיך שמקננו ילך עמנו, אלא גם משלך תתן:
@26 **פרסה.** פרסת רגל פלנט''א בלעז : **לא נדע מה נעבד.** כמה תכבד העבודה שמא ישאל ממנו יותר ממה שיש בידינו:
@29 **כן דברת.** יפה דברת ובזמנו דברת, אמת שלא אוסיף עוד ראות פניך:
@30 **כלה.** גמירא, (כלה) כליל, כלכם ישלח:
@31 **דבר נא.** אין נא אלא לשון בקשה, בבקשה ממך הזהירם על כך שלא יאמר אותו צדיק אברהם (בראשית טו יג) ועבדום וענו אותם קים בהם, (שם יד) ואחרי כן יצאו ברכוש גדול לא קים בהם:
@33 **ויאמר משה כה אמר ה'.** בעמדו לפני פרעה נאמרה לו נבואה זו שהרי משיצא מלפניו לא הוסיף ראות פניו: **כחצת הלילה.** כהחלק הלילה, כחצות, כמו (מלכים א' יט כה) כעלות, (תהלים קכד ג) בחרות אפם בנו, זהו פשוטו לישבו על אפניו, שאין חצות שם דבר של חצי. ורבותינו דרשוהו כמו בחצי הלילה (שמות יב כט) ואמרו, שאמר משה כחצות, דמשמע סמוך לו או לפניו או לאחריו, ולא אמר בחצות, שמא יטעו אצטגניני פרעה, ויאמרו משה בדאי הוא:
@34 **עד בכור השבי.** (שמות יב כט) למה לקו השבויים, כדי שלא יאמרו, יראתם תבעה עלבונם והביאה פרענות על מצרים: **מבכור פרעה עד בכור השפחה.** כל הפחותים מבכור פרעה וחשובים מבכור השפחה היו בכלל. ולמה לקו בני השפחות, שאף הם היו משעבדים בהם ושמחים בצרתם: **וכל בכור בהמה.** לפי שהיו עובדין לה, וכשהקדוש ברוך הוא נפרע מן האמה נפרע מאלהיה:
@36 **לא יחרץ כלב לשנו.** אומר אני שהוא לשון שנון, לא ישנן, וכן (יהושע י כא) לא חרץ לבני ישראל לאיש את לשנו, לא שנן, (שמו''ב ה כד) אז תחרץ תשתנן, (ישעיה מא טו) למורג חרוץ שנון, (משלי כא ה) מחשבות חרוץ, אדם חריף ושנון, (משלי י ד) ויד חרוצים תעשיר, חריפים, סוחרים שנונים: **אשר יפלה.** יבדיל:
@37 **וירדו כל עבדיך.** חלק כבוד למלכות שהרי בסוף ירד פרעה בעצמו אליו בלילה (שמות יב לא) ויאמר קומו צאו מתוך עמי ולא אמר לו משה מתחלה וירדת אלי והשתחוית לי: **אשר ברגליך.** ההולכים אחר עצתך והלוכך: **ואחרי כן אצא.** עם כל העם מארצך: **ויצא מעם פרעה.** כשגמר דבריו יצא מלפניו: **בחרי אף.** על שאמר לו (שמות י כח) אל תוסף ראות פני:
@38 **למען רבות מופתי.** מופתי שנים, רבות שלושה מכת בכורות וקריעת ים סוף ולנער את מצרים:
@39 **ומשה ואהרן עשו** וגו' **.** כבר כתב לנו זאת בכל המופתים, ולא שנאה כאן אלא בשביל לסמכה לפרשה של אחריה:
@40 **ויאמר ה' אל משה ואל אהרן.** בשביל שאהרן עשה וטרח במופתים כמשה, חלק לו כבוד זה במצוה ראשונה שכללו עם משה בדבור: **בארץ מצרים.** חוץ לכרך, או אינו אלא בתוך הכרך תלמוד לומר (לעיל ט כט) כצאתי את העיר וגו' , ומה תפלה קלה לא התפלל בתוך הכרך דבור חמור לא כל שכן, ומפני מה לא נדבר עמו בתוך הכרך, לפי שהיתה מלאה גלולים:
@41 **החדש הזה.** הראהו לבנה בחדושה ואמר לו כשהירח מתחדש יהיה לך ראש חדש. ואין מקרא יוצא מידי פשוטו, על חדש ניסן אמר לו, זה יהיה ראש לסדר מנין החדשים, שיהא אייר קרוי שני, סיון שלישי: **הזה.** נתקשה משה על מולד הלבנה באיזו שעור תראה ותהיה ראויה לקדש, והראה לו באצבע את הלבנה ברקיע, ואמר לו כזה ראה וקדש. וכיצד הראהו, והלא לא היה מדבר עמו אלא ביום, שנאמר (שמ' ו כח) ויהי ביום דבר ה', (ויק' ז לח) ביום צוותו, (במדבר טו כג) מן היום אשר צוה ה' והלאה, אלא סמוך לשקיעת החמה נאמרה לו פרשה זו, והראהו עם חשכה:
@42 **דברו אל כל עדת.** וכי אהרן מדבר והלא כבר נאמר (שמות ז ב) אתה תדבר, אלא חולקין כבוד זה לזה ואומרים זה לזה למדני, והדבור יוצא מבין שניהם, כאלו שניהם מדברים: **אל כל עדת ישראל** וגו' **בעשר לחדש.** דברו היום בראש חדש שיקחוהו בעשור לחדש: **הזה.** פסח מצרים מקחו בעשור, ולא פסח דורות: **שה לבית אבת.** למשפחה אחת, הרי שהיו מרבין יכול שה אחד לכלן, תלמוד לומר שה לבית:
@43 **ואם ימעט הבית מהיות משה.** ואם יהיו מועטין מהיות משה אחד שאין יכולין לאכלו ויבא לידי נותר, **ולקח הוא ושכנו** וגו' **זהו משמעו לפי פשוטו.** ועוד יש בו מדרש ללמד שאחר שנמנו עליו יכולין להתמעט ולמשוך ידיהם המנו ולהמנות על שה אחר, אך אם באו למשוך ידיהם ולהתמעט מהיות משה, יתמעטו בעוד השה קים בהיותו בחיים, ולא משנשחט: **במכסת.** חשבון וכן (ויקרא כז כג) מכסת הערכך: **לפי אכלו.** הראוי לאכילה פרט לחולה וזקן שאינן יכולין לאכול כזית: **תכסו.** תתמנון:
@44 **תמים.** בלא מום: **בן שנה.** כל שנתו קרוי בן שנה כלומר שנלד בשנה זו: **מן הכבשים ומן העזים.** או מזה או מזה שאף עז קרויה שה, שנאמר (דברים יד ד) ושה עזים:
@45 **והיה לכם למשמרת.** זה לשון בקור שטעון בקור ממום ארבעה ימים קדם שחיטה, ומפני מה הקדים לקיחתו לשחיטתו ארבעה ימים מה שלא צוה כן בפסח דורות, היה ר' מתיא בן חרש אומר הרי הוא אומר (יחזקאל טז ח) ואעבור עליך ואראך והנה עתך עת דדים, הגיעה שבועה שנשבעתי לאברהם שאגאל את בניו ולא היו בידם מצוות להתעסק בהם כדי שיגאלו, שנאמר (שם ז) ואת ערום ועריה, ונתן להם שתי מצוות דם פסח ודם מילה, שמלו באותו הלילה, שנאמר (שם ו) מתבוססת בדמיך, בשני דמים, ואומר (זכריה ט יא) . גם את בדם בריתך שלחתי אסיריך מבור אין מים בו, ולפי שהיו שטופים בעבודה זרה אמר להם (פסוק כא) משכו וקחו לכם, משכו ידיכם מעבודה זרה וקחו לכם צאן של מצוה: **ושחטו אתו** וגו' **.** וכי כלן שוחטין אלא מכאן ששלוחו של אדם כמותו: **קהל עדת ישראל.** קהל ועדה וישראל. מכאן אמרו, פסחי צבור נשחטין בשלש כתות זו אחר זו, נכנסה כת ראשונה ננעלו דלתות העזרה וכו' , כדאיתא בפסחים (דף סד א) : **בין הערבים.** משש שעות ולמעלה קרוי בין הערבים, שהשמש נוטה לבית מבואו לערוב. ולשון בין הערבים נראה בעיני אותן שעות שבין עריבת היום לעריבת הלילה, עריבת היום בתחלת שבע שעות מכי ינטו צללי ערב (ירמיה ו ד) , ועריבת הלילה בתחלת הלילה. ערב לשון נשף וחשך, כמו (ישעיה כד יא) ערבה כל שמחה:
@46 **ולקחו מן הדם.** זו קבלת הדם. יכול ביד, תלמוד לומר (פסוק כב) אשר בסף: **המזוזת.** הם הזקופות אחת מכאן לפתח ואחת מכאן: **המשקוף.** הוא העליון שהדלת שוקף עליו כשסוגרין אותו לינט''ר בלעז ולשון שקיפה. חבטה, כמו (ויקרא כו לו) קול עלה נדף, טרפא דשקיף, (שמות כא כה) חבורה. משקופי: **על הבתים אשר יאכלו אתו בהם.** ולא על משקוף ומזוזות שבבית התבן ובבית הבקר, שאין דרין בתוכו:
@47 **את הבשר.** ולא גידים ועצמות: **על מררים.** כל עשב מר נקרא מרור. וצום לאכול מרור זכר לוימררו את חייהם (שמות א יד) :
@48 **אל תאכלו ממנו נא.** שאינו צלוי כל צרכו קראו נא בלשון ערבי: **ובשל מבשל.** כל זה באזהרת אל תאכלו: **במים.** מנין לשאר משקין, תלמוד לומר ובשל מבשל מכל מקום: **כי אם צלי אש.** למעלה גזר עליו במצות עשה וכאן הוסיף עליו לא תעשה אל תאכלו ממנו כי אם צלי אש: **ראשו על כרעיו.** צולהו כלו כאחד עם ראשו ועם כרעיו ועם קרבו, ובני מעיו נותן לתוכו אחר הדחתן. ולשון על כרעיו ועל קרבו כלשון (שמות ו כו) על צבאותם, כמו בצבאותם, כמות שהן, אף זה כמות שהוא, כל בשרו משלם:
@49 **והנתר ממנו עד בקר.** מה תלמוד לומר עד בקר פעם שניה, לתן בקר על בקר, שהבקר משמעו משעת הנץ החמה, ובא הכתוב להקדים שאסור באכילה מעלות השחר, זהו לפי משמעו. ועוד מדרש אחר למד שאינו נשרף ביום טוב אלא ממחרת. וכך תדרשנו והנותר ממנו בבקר ראשון עד בקר שני תעמוד ותשרפנו:
@50 **מתניכם חגרים.** מזמנים לדרך: **בחפזון.** לשון בהלה ומהירות, כמו (שמואל א' כג כו) ויהי דוד נחפז ללכת, (מלכים ב' ז טו) אשר השליכו ארם בחפזם: **פסח הוא לה'.** הקרבן קרוי פסח על שם הדלוג והפסיחה שהקדוש ברוך הוא היה מדלג בתי ישראל מבין בתי מצרים וקופץ ממצרי למצרי, וישראל אמצעי נמלט, ואתם עשו כל עבודותיו לשם שמים. דבר אחר דרך דלוג וקפיצה, זכר לשמו שקרוי פסח וגם פשק''א [פסח] לשון פסיעה:
@51 **ועברתי.** כמלך העובר ממקום למקום, ובהעברה אחת וברגע אחד כלן לוקין: **כל בכור בארץ מצרים.** אף בכורות אחרים והם במצרים, ומנין אף בכורי מצרים שבמקומות אחרים, תלמוד לומר (תהלים קלו י) למכה מצרים בבכוריהם: **מאדם ועד בהמה.** מי שהתחיל בעברה ממנו מתחלת הפרענות: **ובכל אלהי מצרים.** של עץ נרקבת, ושל מתכת נמסת ונתכת לארץ: **אעשה שפטים אני ה'.** אני בעצמי ולא על ידי שליח:
@52 **והיה הדם לכם לאת.** לכם לאות ולא לאחרים לאות מכאן שלא נתנו הדם אלא מבפנים: **וראיתי את הדם.** הכל גלוי לפניו, אלא אמר הקדוש ברוך הוא נותן אני את עיני לראות שאתם עסוקים במצוותי ופוסח אני עליכם: **ופסחתי.** וחמלתי, ודומה לו (ישעיה לא ה) פסח והמליט. ואני אומר כל פסיחה לשון דלוג וקפיצה. ופסחתי מדלג היה מבתי ישראל לבתי מצרים, שהיו שרוים זה בתוך זה, וכן (מלכים א' יח כא) פסחים על שתי הסעפים, וכן כל הפסחים הולכים כקופצים, וכן (ישעיה לא ה) פסח והמליט, מדלגו וממלטו מבין המומתים: **ולא יהיה בכם נגף.** אבל הוה הוא במצרים הרי שהיה מצרי בביתו של ישראל, יכול ימלט, תלמוד לומר ולא יהיה בכם נגף, אבל הוה במצרי שבבתיכם, הרי שהיה ישראל בביתו של מצרי, שומע אני ילקה כמותו, תלמוד לומר ולא יהיה בכם נגף:
@53 **לזכרון.** לדורות: **וחגתם אתו.** יום שהוא לך לזכרון אתה חוגגו. ועדין לא שמענו אי זהו יום הזכרון, תלמוד לומר (שמות יג ג) זכור את היום הזה אשר יצאתם, למדנו שיום היציאה הוא יום של זכרון. ואיזה יום יצאו, תלמוד לומר (במדבר לג ג) ממחרת הפסח יצאו, הוי אומר יום חמשה עשר בניסן הוא של יום טוב, שהרי ליל חמשה עשר אכלו את הפסח ולבקר יצאו: **לדרתיכם.** שומע אני מעוט דורות שנים, תלמוד לומר חקת עולם תחגהו:
@54 **שבעת ימים.** שטיינ''א של ימים: **שבעת ימים מצות תאכלו.** ובמקום אחר הוא אומר (דברים טז ח) ששת ימים תאכל מצות, למד על שביעי של פסח שאינו חובה לאכול מצה, ובלבד שלא יאכל חמץ. מנין אף ששה רשות תלמוד לומר ששת ימים. זו מדה בתורה, דבר שהיה בכלל ויצא מן הכלל ללמד, לא ללמד על עצמו בלבד יצא, אלא ללמד על הכלל כלו יצא, מה שביעי רשות אף ששה רשות, יכול אף לילה הראשון רשות, תלמוד לומר (להלן פסוק יח) בערב תאכלו מצות, הכתוב קבעו חובה: **אך ביום הראשון תשביתו שאר.** מערב יום טוב, וקרוי ראשון לפי שהוא לפני השבעה, ומצינו מקדם קרוי ראשון, כמו (איוב טו ז) הראישון אדם תולד, הלפני אדם נלדת, או אינו אלא ראשון של שבעה, תלמוד לומר (שמות לד כה) לא תשחט על חמץ, לא תשחט הפסח ועדין חמץ קים: **הנפש ההוא.** כשהיא בנפשה ובדעתה, פרט לאנוס: **מישראל.** שומע אני תכרת מישראל ותלך לה לעם אחר, תלמוד לומר במקום אחר (ויקרא כב ג) מלפני, בכל מקום שהוא רשותי:
@55 **מקרא קדש.** מקרא שם דבר, קרא אותו קדש לאכילה ושתיה וכסות: **לא יעשה בהם.** אפלו על ידי אחרים: **הוא לבדו.** הוא ולא מכשיריו שאפשר לעשותן מערב יום טוב: **לכל נפש.** אפלו לבהמה יכול אף לנכרים, תלמוד לומר לכם:
@56 **ושמרתם את המצות.** שלא יבאו לידי חמוץ מכאן אמרו תפח, תלטוש בצונן. רבי יאשיה אומר אל תהי קורא את המצות אלא את המצוות, כדרך שאין מחמיצין את המצה כך אין מחמיצין את המצוה אלא אם באה לידך עשה אותה מיד: **ושמרתם את היום הזה.** ממלאכה: **לדרתיכם חקת עולם.** לפי שלא נאמר דורות וחקת עולם על המלאכה אלא על החגיגה, לכך חזר ושנאו כאן, שלא תאמר אזהרת (לעיל טז) כל מלאכה לא יעשה, לא לדורות נאמרה, אלא לאותו הדור:
@57 **עד יום האחד ועשרים.** למה נאמר, והלא כבר נאמר (לעיל טו) שבעת ימים, לפי שנאמר ימים, לילות מנין, תלמוד לומר עד יום האחד ועשרים וגו' :
@58 **לא ימצא בבתיכם.** מנין לגבולין, תלמוד לומר (להלן יג ז) בכל גבלך. מה תלמוד לומר בבתיכם, מה ביתך ברשותך אף גבולך שב א רשותך, יצא חמצו של נכרי שהוא אצל ישראל ולא קבל עליו אחריות: **כי כל אכל מחמצת.** לענוש כרת על השאור, והלא כבר ענש על החמץ, אלא שלא תאמר חמץ שראוי לאכילה ענש עליו, שאור שאינו ראוי לאכילה לא יענש עליו. ואם ענש על השאור ולא ענש על החמץ, הייתי אומר שאור שהוא מחמץ אחרים ענש עליו, חמץ שאינו מחמץ אחרים לא יענש עליו, לכך נאמרו שניהם: **בגר ובאזרח הארץ.** לפי שהנס נעשה לישראל, הצרך לרבות את הגרים:
@59 **מחמצת לא תאכלו.** אזהרה על אכילת שאור: **כל מחמצת.** להביא את תערבתו: **בכל מושבתיכם תאכלו מצות.** זה בא ללמד שתהא ראויה לאכל בכל מושבותיכם, פרט למעשר שני וחלות תודה:
@60 **משכו.** מי שיש לו צאן ימשוך משלו: **וקחו.** מי שאין לו יקח מן השוק: **למשפחתיכם.** שה לבית אבות:
@61 **אזוב.** מין ירק שיש לו גבעולין: **אגדת אזוב.** שלשה קלחין קרויין אגדה: **אשר בסף.** בכלי, כמו (מלכים ב' יב יד) ספות כסף: **מן הדם אשר בסף.** למה חזר ושנאו, שלא תאמר טבילה אחת לשלש המתנות, לכך נאמר עוד אשר בסף, ושתהא כל נתינה ונתינה מן הדם אשר בסף, על כל הגעה טבילה: **ואתם לא תצאו** וגו' **.** מגיד שמאחר שנתנה רשות למשחית לחבל אינו מבחין בין צדיק לרשע, ולילה רשות למחבלים הוא, שנאמר (תהלים קד כ) בו תרמוש כל חיתו יער:
@62 **ופסח.** וחמל, ויש לומר ודלג: **ולא יתן המשחית.** ולא יתן לו יכלת לבא, כמו (בראשית לא ז) ולא נתנו אלהים להרע עמדי:
@64 **והיה כי תבאו אל הארץ.** תלה הכתוב מצוה זו בביאתם לארץ, ולא נתחיבו במדבר אלא בפסח אחד שעשו בשנה השנית ועל פי הדבור: **כאשר דבר.** והיכן דבר, (שמות ו ח) והבאתי אתכם אל הארץ וגו' :
@66 **ויקד העם.** על בשורת הגאלה וביאת הארץ ובשורת הבנים שיהיו להם:
@67 **וילכו ויעשו בני ישראל.** וכי כבר עשו, והלא מראש חדש נאמר להם, אלא מכיון שקבלו עליהם, מעלה עליהם כאלו עשו: **וילכו ויעשו.** אף ההליכה מנה הכתוב, לתן שכר להליכה ושכר לעשיה: **כאשר צוה ה' את משה ואהרן.** להגיד שבחן של ישראל, שלא הפילו דבר מכל מצות משה ואהרן. ומהו כן עשו, אף משה ואהרן כן עשו:
@68 **וה'.** כל מקום שנאמר וה' הוא ובית דינו, שהוי''ו לשון תוספת הוא כמו פלוני ופלוני: **הכה כל בכור.** אף של אמה אחרת והוא במצרים: **מבכר פרעה.** אף פרעה בכור היה ונשתיר מן הבכורות, ועליו הוא אומר (שמות ט טז) בעבור הראותך את כחי, בים סוף: **עד בכור השבי.** שהיו שמחין לאידם של ישראל. ועוד, שלא יאמרו יראתנו הביאה הפרענות, ובכור השפחה בכלל היה, שהרי מנה מן החשוב שבכלן עד הפחות, ובכור השפחה חשוב מבכור השבי:
@69 **ויקם פרעה.** ממטתו: **לילה.** ולא כדרך המלכים בשלש שעות ביום: **הוא.** תחלה ואחר כך עבדיו, מלמד שהיה הוא מחזר על בתי עבדיו ומעמידן: **כי אין בית אשר אין שם מת.** יש שם בכור מת. אין שם בכור, גדול שבבית קרוי בכור, שנאמר (תהלים פט כח) אף אני בכור אתנהו. דבר אחר מצריות מזנות תחת בעליהן ויולדות מרוקים פנויים, והיו להם בכורות הרבה, פעמים הם חמשה לאשה אחת, כל אחד בכור לאביו:
@70 **ויקרא למשה ולאהרן לילה.** מגיד שהיה מחזר על פתחי העיר וצועק היכן משה שרוי היכן אהרן שרוי: **גם אתם.** הגברים: **גם בני ישראל.** הטף: **ולכו עבדו את ה' כדברכם.** הכל כמו שאמרתם, ולא כמו שאמרתי אני, בטל (שמות ה ב) לא אשלח בטל (שם י ח) מי ומי ההולכים בטל (שם כד) רק צאנכם ובקרכם יצג:
@71 **גם צאנכם גם בקרכם קחו.** ומהו כאשר דברתם, גם אתה תתן בידנו זבחים ועולות (שמות י כה) : **קחו כאשר דברתם וברכתם גם אתי.** התפללו עלי שלא אמות, שאני בכור:
@72 **כלנו מתים.** אמרו לא כגזרת משה הוא, שהרי אמר (לעיל יא ה) ומת כל בכור, וכאן אף הפשוטים מתים חמשה או עשרה בבית אחד:
@73 **טרם יחמץ.** המצריים לא הניחום לשהות כדי חמוץ: **משארתם.** שירי מצה ומרור: **על שכמם.** אף על פי שבהמות הרבה הוליכו עמהם מחבבים היו את המצוה:
@74 **כדבר משה.** שאמר להם במצרים (לעיל יא ב) וישאלו איש מאת רעהו: **ושמלת.** אף הן היו חשובות להם מן הכסף ומן הזהב, והמאוחר בפסוק חשוב:
@75 **וישאלום.** אף מה שלא היו שואלים מהם היו נותנים להם. אתה אומר אחד, טול שנים ולך: **וינצלו.** ורוקינו:
@76 **מרעמסס סכתה.** מאה ועשרים מיל היו ובאו שם לפי שעה, שנאמר (שמות יט ד) ואשא אתכם על כנפי נשרים: **הגברים.** מבן עשרים שנה ומעלה:
@77 **ערב רב.** תערובות אמות של גרים:
@78 **עגת מצות.** חררה של מצה בצק שלא החמיץ קרוי מצה: **וגם צדה לא עשו להם.** לדרך. מגיד שבחן של ישראל, שלא אמרו היאך נצא למדבר בלא צדה, אלא האמינו והלכו, הוא שמפורש בקבלה (ירמיה ב ב) זכרתי לך חסד נעוריך אהבת כלולתיך לכתך אחרי במדבר בארץ לא זרועה, ומה שכר מפורש אחריו (שם ג) קדש ישראל לה' וגו' :
@79 **אשר ישבו במצרים.** אחר שאר הישיבות שישבו גרים בארץ לא להם: **שלשים שנה וארבע מאות שנה.** בין הכל משנלד יצחק עד עכשיו היו ארבע מאות שנה. משהיה לו זרע לאברהם נתקים (בראשית טו יג) כי גר יהיה זרעך, ושלשים שנה היו משנגזרה גזרת בין הבתרים עד שנלד יצחק. ואי אפשר לומר בארץ מצרים לבדה, שהרי קהת מן הבאים עם יעקב היה צא וחשוב כל שנותיו וכל שנות עמרם בנו ושמונים של משה, לא תמצאם כל כך, ועל כרחך הרבה שנים היו לקהת עד שלא ירד למצרים, והרבה משנות עמרם נבלעים בשנות קהת והרבה משמונים של משה נבלעים בשנות עמרם, הרי שלא תמצא ארבע מאות לביאת מצרים, והזקקת לומר על כרחך, שאף שאר הישיבות נקראו גרות, אפלו בחברון, שנאמר (בראשית לה כז) אשר גר שם אברהם ויצחק, ואומר (שמות ו ד) את ארץ מגוריהם אשר גרו בה, לפיכך אתה צריך לומר כי גר יהיה זרעך משהיה לו זרע. וכשתמנה ארבע מאות שנה משנלד יצחק, תמצא מביאתן למצרים עד יציאתן מאתים ועשר שנה, וזה אחד מן הדברים ששנו לתלמי המלך:
@80 **ויהי מקץ שלשים שנה** וגו' **ויהי בעצם היום הזה.** מגיד שכיון שהגיע הקץ לא עכבן המקום כהרף עין, בחמשה עשר בניסן באו מלאכי השרת אצל אברהם לבשרו, בחמשה עשר בניסן נלד יצחק, ובחמשה עשר בניסן נגזרה גזרת בין הבתרים:
@81 **ליל שמרים.** שהיה הקב''ה שומר ומצפה לו לקים הבטחתו להוציאם מארץ מצרים: **הוא הלילה הזה לה'.** הוא הלילה שאמר לאברהם בלילה הזה אני גואל את בניך: **שמרים לכל בני ישראל לדרתם.** משמר ובא מן המזיקין, כענין שנאמר (פסוק כג) ולא יתן המשחית וגו' :
@82 **זאת חקת הפסח.** בארבעה עשר בניסן נאמרה להם פרשה זו: **כל בן נכר.** שנתנכרו מעשיו לאביו שבשמים. ואחד נכרי ואחד ישראל משמד במשמע:
@83 **ומלתה אתו אז יאכל בו.** רבו, מגיד שמילת עבדיו מעכבתו מלאכול בפסח, דברי רבי יהושע. רבי אלעזר אומר אין מילת עבדיו מעכבתו מלאכול בפסח, אם כן מה תלמוד לומר אז יאכל בו, העבד:
@84 **תושב.** זה גר תושב: **ושכיר.** זה הנכרי. ומה תלמוד לומר, והלא ערלים הם, ונאמר (פסוק מח) וכל ערל לא יאכל בו, אלא כגון ערבי מהול וגבעוני מהול והוא תושב או שכיר:
@85 **בבית אחד יאכל.** בחבורה אחת, שלא יעשו הנמנין עליו שתי חבורות ויחלקוהו. אתה אומר בחבורה אחת, או אינו אלא בבית אחד כמשמעו, וללמד שאם התחילו והיו אוכלים בחצר וירדו גשמים שלא יכנסו לבית, תלמוד לומר (פסוק ז) על הבתים אשר יאכלו אותו בהם, מכאן שהאוכל אוכל בשני מקומות: **לא תוציא מן הבית.** מן החבורה: **ועצם לא תשברו בו.** הראוי לאכילה, כגון שיש עליו כזית בשר יש בו משום שבירת עצם, אין עליו כזית בשר אין בו משום שבירת עצם:
@86 **כל עדת ישראל יעשו אתו.** למה נאמר, לפי שהוא אומר בפסח מצרים (פסוק ג) שה לבית אבות, שנמנו עליו למשפחות, יכול אף פסח דורות כן, תלמוד לומר כל עדת ישראל יעשו אותו:
@87 **ועשה פסח.** יכול כל המתגיר יעשה פסח מיד, תלמוד לומר והיה כאזרח הארץ, מה אזרח בארבעה עשר אף גר בארבעה עשר: **וכל ערל לא יאכל בו.** להביא את שמתו אחיו מחמת מילה שאינו משמד לערלות ואינו נלמד מבן נכר לא יאכל בו (פסוק מג) :
@88 **תורה אחת** וגו' **.** להשוות גר לאזרח אף לשאר מצות שבתורה:
@92 **פטר כל רחם.** שפתח את הרחם תחלה, כמו (משלי יז יד) פוטר מים ראשית מדון, וכן (תהלים כב ח) יפטירו בשפה, יפתחו שפתים: **לי הוא.** לעצמי קניתים על ידי שהכיתי בכורי מצרים:
@93 **זכור את היום הזה.** למד שמזכירין יציאת מצרים בכל יום:
@94 **בחדש האביב.** וכי לא היו יודעין באיזה חדש, אלא כך אמר להם, ראו חסד שגמלכם שהוציא אתכם בחדש שהוא כשר לצאת, לא חמה ולא צנה ולא גשמים. וכן הוא אומר (תהלים סח ז) מוציא אסירים בכושרות, חדש שהוא כשר לצאת:
@95 **אל ארץ הכנעני** וגו' **.** אף על פי שלא מנה אלא חמשה עממין, כל שבעה גוים במשמע, שכלן בכלל כנעני הם, ואחת ממשפחות כנען היתה שלא נקרא לה שם אלא כנעני: **נשבע לאבתיך** וגו' **.** באברהם הוא אומר (בראשית טו יח) ביום ההוא כרת ה' את אברם וגו' , וביצחק הוא אומר (שם כו ג) גור בארץ הזאת וגו' , וביעקב הוא אומר (שם כח יג) הארץ אשר אתה שוכב עליה וגו' : **זבת חלב ודבש.** החלב זב מן העזים והדבש זב מן התמרים ומן התאנים: **את העבדה הזאת.** של פסח. והלא כבר נאמר למעלה (יב כה) והיה כי תבאו אל הארץ וגו' , ולמה חזר ושנאה, בשביל דבר שנתחדש בה. בפרשה ראשונה נאמר (שם כו) והיה כי יאמרו אליכם בניכם מה העבודה הזאת לכם, בבן רשע הכתוב מדבר שהוציא את עצמו מן הכלל, וכאן (פסוק ח) והגדת לבנך, בבן שאינו יודע לשאל, והכתוב מלמדך שתפתח לו אתה בדברי אגדה המושכין את הלב:
@98 **בעבור זה.** בעבור שאקים מצותיו, כגון פסח מצה ומרור הללו: **עשה ה' לי.** רמז תשובה לבן רשע לומר, עשה ה' לי ולא לך, שאלו היית שם לא היית כדאי לגאל:
@99 **והיה לך לאות.** יציאת מצרים תהיה לך לאות: **על ידך ולזכרון בין עיניך.** שתכתוב פרשיות הללו ותקשרם בראש ובזרוע: **על ידך.** יד שמאל, לפיכך ידכה מלא בפרשה שניה (פסוק טז) לדרוש בה, יד שהיא כהה:
@100 **מימים ימימה.** משנה לשנה:
@101 **והיה כי יבאך.** יש מרבותינו שלמדו מכאן שלא קדשו בכורות הנלדים במדבר, והאומר שקדשו מפרש ביאה זו לומר אם תקימוהו במדבר תזכו לכנס לארץ ותקימוהו שם: **נשבע לך.** והיכן נשבע לך, (שמות ו ח) והבאתי אתכם אל הארץ אשר נשאתי וגו' : **ונתנה לך.** תהא בעיניך כאלו נתנה לך בו ביום, ואל תהי בעיניך כירשת אבות:
@102 **והעברת.** אין והעברת אלא לשון הפרשה, וכן הוא אומר (במדבר כז ח) והעברתם את נחלתו לבתו: **שגר בהמה.** נפל ששגרתו אמו ושלחתו בלא עתו, ולמדך הכתוב שהוא קדוש בבכורה לפטור את הבא אחריו. ואף שאינו נפל קרוי שגר, כמו (דברים ז יג) שגר אלפיך. אבל זה לא בא אלא ללמד על הנפל שהרי כבר כתיב כל פטר רחם. ואם תאמר אף בכור בהמה טמאה במשמע בא ופרש במקום אחר (דברים טו יט) בבקרך ובצאנך. לשון אחר יש לפרש והעברת כל פטר רחם, בבכור אדם הכתוב מדבר:
@103 **פטר חמר.** ולא פטר שאר בהמה טמאה, וגזרת הכתוב היא לפי שנמשלו בכורי מצרים לחמורים. ועוד, שסיעו את ישראל ביציאתן ממצרים, שאין לך אחד מישראל שלא נטל הרבה חמורים טעונים מכספם ומזהבם של מצרים: **תפדה בשה.** נותן שה לכהן ופטר חמור מתר בהנאה והשה חלין ביד כהן: **וערפתו.** עורפו בקופיץ מאחוריו והורגו. הוא הפסיד ממונו של כהן, לפיכך יפסיד ממונו: **וכל בכור אדם בבניך תפדה.** חמש סלעים פדיונו קצוב במקום אחר:
@104 **כי ישאלך בנך מחר.** יש מחר שהוא עכשיו, ויש מחר שהוא לאחר זמן, כגון זה וכגון (יהושע כב כד) מחר יאמרו בניכם לבנינו, דבני גד ובני ראובן: **מה זאת.** זה תינוק טפש שאינו יודע להעמיק שאלתו וסותם ושואל מה זאת, ובמקום אחר הוא אומר (דברים ו כ) מה העדות והחקים והמשפטים וגו' , הרי זאת שאלת בן חכם. דברה תורה כנגד ארבעה בנים, רשע ושאינו יודע לשאל והשואל דרך סתומה והשואל דרך חכמה:
@106 **ולטוטפת.** תפלין, ועל שם שהם ארבעה בתים קרויין טטפת, טט בכתפי שתים, פת באפריקי שתים. ומנחם חברו עם (יחזקאל כא ב) והטף אל דרום, (מיכה ב ו) אל תטיפו, לשון דבור, כמו (לעיל פסוק ט) ולזכרון, שהרואה אותם קשורים בין העינים יזכור הנס וידבר בו:

@1 **ויאמר ה' אל משה**. אמר ל' אמירה רכה גם הזכיר שם הרחמים לא לצד המשתלח אליו אלא לצד השליח שהוזכר בסמוך אל משה כי הם דברים שישמח בהם צדיק כי חזה נקם לזה אמר ל' אמירה והזכרת שם הרחמים כי הם דברים הסועדים את לבו:
@1 **עוד** לצד שלא היה ה' שולח המכה תכף ומיד עד שהי' שולח להתרות בו קודם למר שבוע א' (שמו''ר פ''ט) ולמר ג' שבועות, וזה הוא ממדת החסד והרחמים לזה אמר לשון אמירה וזכרון שם הרחמים. עוד ירצה על דרך שפירשתי למעלה בפרשת וארא (ו' ב') כי אפילו מדת הרחמים הסכימה בשמחה לעשות דין ולהנקם מאויב זה:
@1 **כי** אני הכבדתי. פי' מעתה תשכיל לדעת כי אני הוא שהכבדתי את לבו כי מטבע אדם לו יהי' לבו קשה כאבן ירעד ויפחד בראותו מכת הברד וזה האיש עודנו ברשעו אין זה ממדת אדם אלא אלהים גזר עליו להקשותו. ולפי מה שפירשתי בפסוק (לעיל ט' ל''ב) והחטה והכוסמת וגו' כי אפילות וגו' כי ה' עשה פלאי פלאים וזה היה סיבה להכביד לבו ידוייק גם כן על נכון כי אני הכבדתי בעשות פלא זה:
@1 **או** ירצה לדרך זה כי לצד שראה משה המכה הגדולה של הברד ורשע זה אדרבה הוסיף לחטוא ישלול התקוה ממנו ויתחמץ לבבו בשליחותיו אל פרעה לזה אמר לא תחוש לזה **כי אני הכבדתי לבו** וזולת זה כשארף ממנו כובד לב הנה הוא משלחם:
@1 **ואת** לב עבדיו. טעם כובד לב עבדיו הוא לבל יעצוהו לשלח גם שבזה תהיה הבאת המכות לכל מצרים ולא לפרעה לבד כי בזה לא יהי' פרסום המכות אשר יביא ה' על פרעה לבד והגם שלא הזכיר ה' פרט זה בשליחות ראשונה ולא אמר אלא אחזק את לב פרעה אמר העיקר ובכללו הם עבדיו ואולי שנתכוין ה' בדבריו כאן לפרש לו דבריו הראשונים שלא לב פרעה לבד אלא גם לב עבדיו וטעם שלא ביאר מקודם וביאר עתה לצד שאמר משה בפרשה הקודמת ואתה ועבדיך גילה דעתו כי הוא סובר שאין הזכרת עבדיו נכללת בהזכרת פרעה ומעתה יבין בדברי ה' שאמר לו ואני אחזק את לב פרעה כי אין עבדיו בכלל ויחשוב כי חיזוק לב עבדיו לא מה' יצא הדבר לזה אמר **אני הכבדתי את לבו ואת לב עבדיו**:
@1 **למען שיתי אותותי אלה בקרבו**. צריך לדעת למה דקדק לומר **אותותי אלה** שיראה שעיקר הטעם שהכביד לבו הוא לצד אותות אלה לשומם שנראה שיש צורך בשימת אותות אלה ולא זולתם, עוד אומרו **בקרבו** ויתבאר על דעך אומרם ז''ל (שמו''ד פי''ב) כי מעשה מצרים מעיד על האלהות כי הוא השליט והוא האדון, והאדון לצד שחפץ בישראל לקרבם לעבדו ולדבקה בו היה חפץ להשכילם לראות ולהביט בעין הכחשת כל אמונה חוץ ממנו, ועדיין לא הראם כי הוא בורא רוח ועושה מלאכיו רוחות, גם לא הראם כי הוא בורא אור וחושך, ולזה אמר **למען שיתי** וגו' פירוש לצד שאמר אליו כי אני הכבדתי את לבו יש מקום למשה לומר למה יאריך עוד הטורח ויצטרך גם כן לשדד המערכות כי יש בכל מכה שינוי סדר מערכת הבריאה, אם להראותו את כוחו יתברך אשר אמר עליו מי ה' הלא הכה מכת הברד והראהו ה' ידו הנפלאה ומה צורך להפך סדר הבריאה עוד, לזה אמר אליו טעם למען שיתי אותותי אלה פירוש אותות שאני רוצה לעשות בעולמי כדי שיכירו ישראל האלהות עדיין נשארו מהם אלה להשלמת האמונה, כי בכל שבע מכות שעברו אין בהם הכחשה למשתחוה לשמש או לירח, גם לאשר יטעה כי בורא הרוח אינו בורא העפר, והגם ששלט ה' על הארץ במה יודע כי הוא בורא רוח הוא היוצר אדם וצר צורה, והוצרך ה' להראותם במעשה הארבה כי עשה מלאכיו רוחות להביאם גם להחזירם, גם לשאת את המתים לבל יהנו מהם המצריים (שם פי''ג) ובמכת חושך כי הוא יוצר המאורות ושלט בהם, גם יצירת החושך וגזר עליו לשמש עבות למצרים (שם פי''ד), ובמכת בכורות נודע כי הוא היוצר צורה בתוך צורה ומכיר טיפת הבכור (ב''מ ס''א:) גם באמצעות מכה זו צוה ה' מצות (לקמן י''ג ב') קדש לי כל בכור, ויהיה זה לזכרון כי הוא יוצרו מבטן לעבד לו, ולזה כשמצא רשע זה הקשה ה' לבו למען שיתי אותותי אלה שאני צריך לעשות לאות ולמופת לטעם הנזכר יהיו בקרבו שתמצאנה אותו כוסות התרעלה גם כן לצד רשעו וזולת טעם זה לא היה ה' משדד המערכות בשבילו לבד:
@2 **ולמען תספר וגו** '. צריך לדעת לאיזה ענין הוצרך לטעם זה ולא הספיק בטעם הראשון שה' חפץ להשים אותות אלה כמו שפירשתי בסמוך. עוד מה הוא את אשר התעללתי במצרים ומה הוא ואת אותותי שנראה שהם ב' דברים. עוד צריך לדעת כוונת אומרו **וידעתם** וגו':
@2 **אכן** כוונת הכתוב הוא כי בא ה' להודיע כי אין תכלית הכוונה בהבאת האותות בקרבו לעשות נקמה בפרעה אלא לחזק האותו' שבהם עיקר האמונה בלב ישראל כדי שיהיה רשום בל ישכח לנצח כי כשיהי' בקרבו של פרעה יהי' בזכרון בני ישראל לעולם ועד והכוונה ע''ד אומרם ז''ל במם' חולין (עה:) בדין בן פקועה כ''א יהיו בו ב' דברים המופלאים יהי' מוזכר תמיד וכשיראו שאוכלו בלא שחיטה לא יחשדוהו כי מוזכר הוא ביניהם כי תרי תמיהי מדכר דכירי אינשי והנה באמצעות הפלא שיפליא ה' להודיעם כי הוא שולט ברוח ובמים ובעפר ובבעלי חיים ובאש ובאויר וכדומה אין זה מספיק שיזכר הדבר בתמידות לעולם לחקק האמונה אלא באמצעות היות הפלאה ב' כי יפליא ה' להרע את פרעה ועבדיו להשקותם כוסות לענה מה שלא הי' כן לכל גוי וזה לך נעימות אמרי נועם ולמען תספר באזני בנך ענין זה והסיפור מן הנמנע שיהיה הדבר תמיד בזכרונך זולת באמצעות ב' תמיהות, הא' **את אשר התעללתי במצרים** הרי תמיה אחת הגם שהי' ה' עושה להם צרות שאין בהם שדוד המערכות והטבעיות אעפ''כ לצד רוב הצרות והמכות עשר מכות וכל מכה היתה של ארבע וה' מכות לא עשה כן לכל גוי הנה הדבר תמוה ותמיה זו לבד לא דכירי אינשי ולא יספרו מעשה ה' ואמר **ואת אותותי** פי' האותות שעשה ה' תמיה' שנית שגם בלא ענין מצרים האות מעצמו הוא דבר פלא ובאמצעות ב' פלאות תספר באזני בנך ובן בנך וגו' ותכלית המכוון בסיפור הוא וידעתם כי אני ה' ואין עוד ותכזיבו האמונות זולת זה וכן תמצא כשדבר אתנו ה' ב''ה בהר סיני פתח דבריו ית' אמר אנכי ה' אלהיך וזה לך האות אשר הוצאתיך מארץ מצרים והוא שהקדים דבריו כאן ואמר וידעתם כי אני ה' כי יכירו בזה בחוש הראות צדק האמונה מה שלא השיג אדם מהעולם עד העולם ברוך אשר כן עשה לנו:
@6 **ויפן ויצא**. זלזלו בעיניו שאחר שהתוודה ואמר ה' הצדיק וגו' וחזר לסרחונו לזה פנה ויצא כדרך הנהוג עם שאר בני אדם ותמצא כי גם פרעה הרשע שילם לו כן דכתיב ויושב וגו' ויגרש אותם מאת פני פרעה ולזה תמצא שאח''כ כשקרא לו להתפלל על הסרת מכת הארבה אמר אליהם חטאתי לה' ולכם מה שלא היה רגיל לומר קודם שנתכוון להתודות על שנהג בם מנהג פחיתות ויגרש אותם:
@7 **עד מתי יהי' וגו'**. לא שהסכימו לשלח ישראל בהחלט כי הנבואה שאמר ה' למשה הכבדתי וגו' תכחיש זה אלא שרצו שילכו באופן שיחזרו ודאי ולזה תמצא כשאמר משה בנערינו ובזקנינו וגו' וגרש' פרעה לא יספו דבר עוד בדבר הזה גם פיהם ענה בם כי לא האמינו בסדר המעשה כי אלהי העברים הגדול הגבור והנורא נטה ידו בהם לשלוח ישראל אלא שהיו יוקשים בהם ואין לך כפירה באמיתות הענין כזה:
@7 **הטרם תדע**. פי' האם קודם שתשלחם תרצה לדעת שאבדה מצרים לזה שלח אותם קודם שיגיע גדר זה של אבידת מצרים:
@7 **וראיתי** לתת לב במה הסכימה דעתם על אבידת מצרים אחר כך ושתקו והלכו להם ולהבין הענין נשכיל בחקור בענין מה היתה דעתו של פרעה ועבדיו מתחילת הענין האם יש שוטה גמור בעולם שיסבול כל הרעות והצרות ההמה ויכנים עצמו בסכנות נפשות ועוד לו שלקה אלוהו וספו מקניו ואבדו צמחי אדמה וכמעט ספו תמו כאומרו הטרם תדע כי אבדה מצרים ומהן הסתם לא יאמן כי כ''כ טפש היה והגם כי הקשה ה' את רוחו עכ''ז צריך שתהיה לו איזה סברא שבה יתגלה טפשותו ותגדל הקושיא בראות כי לא שאל ה' ממנו אלא דרך שלשת ימים והגם שכתבנו שם (לעיל ג' י''ח) כי ה' לא אמר פדט זה אלא ישראל עם כל זה הרי בכל שליחותיו לא אמר אלא (ה' א') ויחוגו לי במדבר, ויעבדוני (פסוק ג'), זה יגיד כי לא לחלוטין יצו ה'. ואבין דבר כי הוא זה אשר הטעהו לפרעה ולכל עמו אופן השליחות אשר שלח ה' לשלוח ישראל לחוג במדבר שהכוונה הוא לשוב אחר כך הרי הוא גלוי לפרעה ולעמו כי לא בהחלט הוא שואל ומזה נפל הטעות כי יש בדבר שני צדדין הא' כי דבר ה' אמת הוא כי אינו חפץ אלא דרך שלשת ימים והב' כי הדברים באו דרך ערמה ואין דעתו אלא להוציאם לחלוטין ולפי זה הדברים מעידים כי כביכול אין כח בו להוציאם בהחלט ב''מ הא למדת שיש לו מניעה חם ושלום לרצון אשר יחפוץ ולזה פרעה ועבדיו לצד שלילת עיקר האמונה בהם חשבו צד הב' ולזה הקשו ערפם ומאנו לקבל מאמר ה' כי אמרו אין בכוחו ח''ו להכריח הכרח גדול וזה לך האות המופלא שערום יערים ולזה הקשו לבם ואחר כך כשראו עבדיו שעברו עליהם שבע מכות והתרה במכה שמינית של הארבה נתנו לב לצדד צד הא' כי האמת הוא שטעמו של האלוה ב''ה הוא שאינו חפץ להוציאם לחלוטין. והוא אומרם **עד מתי יהיה** וגו' **שלח את האנשים ויעבדו** פי' שאין כוונת ה' אלא על פרט זה והטעם שבו הכרחנו הדבר כי הכרנו כי כל יכול ואם היתה כוונתו שילכו לחלוטין היה אומר כן בפירוש ויאבד כל מסרב וממאן בדבריו ואמרו **הטרם תדע כי אבדה מצרים** במכות אשר הכה הא למדת כי יכול הוא לעשות כל אשר יחפוץ ולפי זה הכריחו שני דברים הא' שישראל לא ילכו בהחלט והצדיקו מפלאי המכות כ''א היה ה' חפץ להוציאם בהחלט אין מידו מציל. ותמצא כי נתחכם פרעה הרשע והשיבם במרמה ויושב את משה וגו' ויאמר להם מי ומי ההולכים והשיבוהו בנערינו ובזקנינו נלך ואמר להם רעה נגד וגו' לכו נא הגברים וגו' כי אותה אתם מבקשים ויגרש אותם וגו' ומאמצעות המעשה נסתרה דעת עבדי פרעה כי לא כמו שחשבו שאין הליכתם אלא לשעה שהרי מהענין מוכח כי ערמה בדבר והליכתם הליכת עולם ולפ''ז חזרו ג''כ למיחוש הראשון כי זה לך האות כי לא כל יכול כנזכר למעלה ובזה לא הוסיפו לדבר עוד כדבריהם הראשונים:
@8 **לכו** עבדו וגו'. אמר סתם הדברים ונתחכם להרחיק שלא יעלה על הדעת שישאלו שילכו כולם ולזה דיבר סתם לכו עבדו ואמר **מי ומי** לא לומר אם כולם אם מהם זה ' ודאי שלא ילכו אלא בני העבודה כמו שגילה לבסוף לכו הגברים כי אותה אתם מבקשים אלא גם בגברים היה חפץ שלא ילכו כולם:
@12 **בארבה**. אולי שיקשור ארבה אחד במטהו או אפשר שיזכיר שם הארבה בנטותו את ידו לסי' כי נטית ידו הוא בשביל ארבה:
@22 **ויט** משה את ידו. צל''ד למה במכת הארבה הסמוכה לה הגם שאמר אליו ה' נטה ידך אמר הכתוב ויט מה את מטהו וגו' וגם בכל המכות לא היתה מכה שהזכיר בה נטית יד אלא מטה ובמכה זו אמר **את ידו**. ואולי שיתכוין ע''פ דבריהם ז''ל (שמו''ר פי''ז) כי חושך של מצרים היה מאותו חושך דכתיב תהלים י''ח ישת חושך סתרו אשר ע''כ לא נהג מנהג מיעוט דרך כבוד לנטות מטהו כלפי מעלה:
@22 **גם** ליש מרבותינו שאמרו (שמו''ר שם) שחושך זה היה מגיהנם אולי כי שניהם נתכוונו אל האמת כי ב' מיני חושך היו אחד ששמש בג' ימים שלא ראו וגו' וא' ששמש בג' ימים אחדים שלא קמו וגו':
@23 **ולכל** בני ישראל היה אור וגו'. דקדק לומר **ולכל** לומר שכל אחד ואחד מישראל שהיה הולך לבית המצרי היה לו אור במושבותם של המצריים. או יכוין לומר אור זה מנין מוצאו ואמר שהוא **אור במושבותם** וחסר תיבת אשר והרבה מקראות יקצרו כן והכוונה ע''ד אוז''ל (שם) כי הרשעים מתכסים בחושך והוא אשר כיסה המצרים הרשעים וכנגד הצדיקים עליהם יזרח ה' ב''ה ואוהביו כצאת השמש בגבורתו ומאור מושבותם ליוה להם ה' ב''ה חלק א' והוא אומרו **אור במושבותם**:
@24 **ויקרא** פרעה וגו'. פי' אחר ששלמו ימי החשך כי קודם לא קמו איש וגו', ולזה דיבר הרשע קשות למשה ואמר לו אל תוסף וגו' ראותך פני תמות, כי אם חושך ישופהו היה מדבר תחנונים:
@24 **גם** טפכם. טעם שלא הסמיך ההולכים יחד ואח''כ המוצגים עז''ה לכו עבדו וגו' גם טפכם גם צאנכם רק צאנכם וגו' אולי שנתחכם הרשע להקדים התנאי קודם למעשה וזה שיעור דבריו **לכו עבדו** כדברי הראשונים שהגברים הם העובדים ולא הטף רק אם תעשו תנאי זה **שצאנכם** וגו' **יוצג** בתנאי זה **גם טפכם ילך** וגו' וזולת התנאי לא ילכו אלא העובדים שהם הגברים ולא הטף ואם היה מקדים המעשה לומר גם טפכם וגו' ואח''כ יאמר רק צאנכם המעשה קיים והתנאי בטל ואולי שגם בין הגוים יקפידו על דיוק זה להיות דברי סברא והם דברים הרגילים במקח וממכר:
@25 **גם** אתה תתן בידנו. קשה איך שאול ישאל עבד ה' זבחי אלהים מאיש בזוי וטמא אשר הרים פיו בקדוש ישראל נוסף על היותו נכרי החפץ לה' בזבח רשעים והגם שאמרה תורה איש איש לרבות (חולין י''ג:) אך ורק לא לשאול ממנו. אכן דברי פי חכם דקדק בלשונו ואמר **ועשינו** שהיל''ל לעשות לה' אלהינו אלא נתכוונו לומר שהוא יתן בידם מקנה הראוי לזבחים ואנחנו נעשה לה' אלהינו לצורך עצמנו אלא שהוא ימציא להם מתנה שיסתפקו ממנה לזבחיהם לה' גם בזה לא קשה אומרו זבחים ועולות לתנא שאמר (מנחות ע''ג:) שאין מקבלין מאו''ה אלא עולה ולא שלמים והרי מקרא מלא דיבר הכתוב כאן זבחים ועולות ולדברינו לא קשה:
@26 **וגם מקנינו וגו'**. צריך לדעת למה הוצרך להזכיר אחר שכבר אמר אליו גם אתה תתן זה יגיד שמלבד שיקחו מקניהם גם אתה וגו'. אם כן הרי הזכיר מקניהם, והיה נראה לומר שחש שיבין פרעה כי אומרו גם אתה לא ירמוז הקודם על מקניהם אלא על הטף כי מלבד שילך הטף גם צריך הוא ליתן וגו', לזה ביאר הדברים שעל המקנה, זה דוחק. עוד צריך לדעת כונת אומרו **כי ממנו נקח** וגו' מה חידוש בזה אם להודיעו שעובדים ה' בזביחת צאן, הלא כבר אמר אליו גם אתה תתן בידינו זבחים וגו' אם כן אין חידוש בהודעה זו. עוד צריך לדעת אומרו לא נדע מה נעבוד כי פשט הדברים יגיד בזה הוא על השיעור שאינם יודעים כמה תכבד העבודה ולזה צריכין למקניהם וגם הוא יתן אם יחפוץ, אם כן היה לו לומד כמה נעבוד. אכן נראה כי נתכוין לשלול טענה אחת לבל יטעון אותה פרעה והוא כי יקחו מין הראוי לזבוח לה' ומין שאינו ראוי יוצג לזה אמר וגם מקנינו ילך עמנו פירוש אפילו אותם שאינם ראוים לזביחה, ולזה גמר אומר **לא תשאר פרסה** פירוש כל רגל בהמה ובכלל זה נכלל סוס ופרד גמל חמור וכו' כי כולם יקרא להם מקנה. ואומרו כי ממנו נקח יתבאר על דרך אומרם במסכתא (ע''ז כ''ד:) וזה לשונם ת''ש וכו' אשר חמל העם על מיטב הצאן וגו' למען זבוח לה' וגו' מאי מיטב דמי מיטב ומ''ש דאקפץ עליהם זבינא ע''כ. הנה שהגם שאמר הכתוב למען זבוח לה' מפרש לה התלמוד למען קנות מדמיהן זבחים וכמו כן יתבאר אומרו כאן **כי ממנו נקח** פירוש הגם שאינם ראוים לזביחה אף על פי כן יצטרך לנו לטעם **כי ממנו** פירוש מדמיו נקח לעבוד ה' פירוש צורכי עבודה, ולזה לא אמר ממנו נזבח לה' אלהינו:
@26 **ואומרו ואנחנו לא נדע מה נעבוד** פירוש ואם תאמר נשער שיעור המספיק לעבודה והשאר יוצג, לזה אמר לא נדע מה נעבוד תיבת מה תסבול ב' עניינים ולב' נתכוון, הא' הוא כמה, והב' מה הוא אופן העבודה שיצו האל אותנו, כי אפשר שיאמר שנבנה בנין לזבוח בו וכלי זהב אין שיעור ואבנים טובות ומרגליות ועבודות אחרים, והגם שאמרו ונזבחה וגו' הרי אמר עוד שלח עמי ויעבדוני והכניס פרטים אחרים בכלל זה מלבד הזביחה באופן שאין דבר זה של הזביחה מסויים שאין זולתה, אשר על כן אנו צריכין לכל מה שיש לנו וגם אתה תתן. ואומרו **עד בואנו שמה** נתחכם להשיב כי יאמר אליו הלא נביא אתה ושאל לך דבר זה מה' ויתברר הענין ויוצג דבר שאין בו צורך, לזה אמר עד בואנו שמה פירוש שאין זה מהמוסר לשאול את אלהינו על הדבר לדעת מה יחפוץ עד בואנו שמה במקום העבודה אז נדע הדבר. ואולי כי לצד שפרעה לא הצדיק תשובה זו וחשד כי משה ערום יערים עליו ודברי עצמו משיב ואין חם ושלום בפיהו נכונה כי מן הסתם יודעים גם יכולים לידע אלא משה מפי עצמו אמר תשובה זו לנגדו לזה נתכעס עליו ואמר אליו אל תוסף ראות פני וגו':
@27 **ויחזק ה' וגו' ולא אבה וגו'**. יעיד הכתוב כי בפעם הזאת החליט בדעתו שלילת שליחות ישראל ולא נשאר בדעתו לחשוב מחשבות אם יחוש למכות או אם יסבול מכות הגדולות אלא חתם הדבר יעבור על דברי ה' הגם שיהרג:
@27 **או** ירצה שנתחכם לעשות אופן שלא יבואו עליו עוד מכות ובזה אין הכרח לשלחם והוא מה שאמר סמוך לאומרו ולא אבה **ויאמר לו פרעה לך מעלי** וגו', הכוונה בזה כי לצד שהשכיל בתשע מכות שבאו עליו שכולן היו על זה האופן ב' בהתראה ואחד בלא התראה למאן דאמר ג' שבועות היה מתרה על כל מכה ומכה ולמאן דאמר שבוע א', אמר מעתה במכה זו הבאה תתחייב להיות ההתראה ואם אין התדאה אין מכה, לזה נתחכם ואמר השמר לך אל תוסף ראות פני וכיון שכן אין התראה וכיון שאין התראה אין מכה. והנה לא הקשה ה' את לבו לעשות כן אלא עד כלות ט' מכות ולא נשארה אלא מכת בכורות, ולזה אמר משה **כן דברת לא אוסיף עוד** וגו', ופירוש דברי משה כבר פירשתי אותם בפרשת וארא בפסוק (ז' ג') ואני אקשה, ולא ישמע אליכם פרעה וגו':
@27 **ובדרך** רמז ירצה באומרו **כן דברת** תשובה למה שאמר לו ביום ראותך פני תמות השיבו כי אינו יכול להמית ואין בידו אלא כח הדיבור, והוא אומרו כן דברת ולא כן תעשה. או ירצה על זה הדרך כבר דברת כן פעם אחרת, והמכוון הוא ראה מה עלתה בידך כאומרם ז''ל (שמות רבה פ''א) בפסוק (ב' ט''ו) ויבקש להרוג את משה ולא עלתה בידו, גם אמרו (ילקוט קע''ה) שהרג כל שועריו שהניחו למשה ליכנם והשיבו כי אין להם שליטה עליו, ואם כן הבזוי איך מחליט לומר ביום וגו' תמות. וכנגד הענין מצד עצמו שאין אתה חפץ לראות פני גם אני אין אני חפץ להסתכל בדמותך לא אוסיף וגו':
@30 **ויאמר ה' וגו' עוד נגע וגו'**. פרשה זו מגדת מה שכבר אמר ה' קודם. ותמצא כי התחלת המכות נבואה ראשונה שהיתה במדין אמר לו (ג' י''ט) לא יתן אתכם מלך מצרים להלוך ולא ביד חזקה ושלחתי את ידי וגו' ונתתי את חן העם וגו' ושאלה וגו'. ונבואה ב' גם כן במדין הודיעו מכת בכורות דכתיב (ד' כ''ב) בני בכורי וגו' ותמאן לשלחו הנה אנכי הורג את בנך בכורך הרי בידו מכת בכורות באחרונה. ונבואה ג' בארץ מצרים אמר אליו (ז' ד') כי סימן סוף המכות הוא כשלא ישמע להם פרעה פירוש שלא ירצה לשמוע דבריהם עוד, אשר על כן כשאמר לו אל תוסף וגו' מזה ידע כי הגיע זמן מכה האחרונה שבה יצאו וידע אותה כי היא זו מכת בכורות ששקולה כנגד כל וכו' הנאמרת אליו בסמיכות מצות ושאלה אשה משכנתה, והוא מה שאמר הכתוב **ויאמר ה' עוד נגע** וגו' פירוש כבר אמר ה' עוד וגו' פירוש שהוא מה שכתב בנבואות הראשונות כמו שרשמתי, ולזה אמר משה תיכף אל פרעה כה אמר ה' כחצות הלילה וגו'. והגם שלא מצינו שאמר לו ה' שם פרט זה של כחצות, ילמד סתום מהמפורש כי כן היו שם הדברים אלא שקצר וממקומו אתה למד כי כן אמר אליו ה'. ומעתה לא נאמרה נבואה זו במצרים, גם לא קשה למה יצו ה' פעמים על שאלת כלים ממצרים:
@33 **כחצות הלילה**. כבר דברו רבותינו ז''ל (כרכות ד'.) בטעם אומרו כחצות בכ''ף. ואולי שיכוין עוד על דרך אומרם ז''ל (בראשית רבה פמ''ג) בפסוק (בראשית י''ד ט''ו) ויחלק עליהם לילה כי ליל ט''ו בניסן היה. עוד אמרו ז''ל (בראשית רבה פמ''ב) כי הריגת ד' מלכים שהרג אברהם אבדה כמה אמונות, גם היתה מלחמה גדולה ועצומה ורשומה במלכי עולם כי היו מלכים תקיפים ושלטו על ה' מלכים גדולים ותקיפים ואדם אחד הוא ועבדי ביתו נצחום, לזה ציין לו הזמן ואמר לו **כחצות הלי**. לה הידוע בעולם שיצאתי לישע אברהם אביהם כמו כן אני יוצא וגו':
@33 **אני יוצא וגו'**. פירוש הגם שיש לי כמה משרתים אף על פי כן אני בעצמי אצא בתוך מצרים, והטעם לב' סיבות, א' לחיבת הבנים שתהיה יציאתם על ידו בכבודו
@33 יבעצמו, ב' כי אין מלאך מבחין ההבחנה הגדולה מי הוא שנוצר מטפה ראשונה של אדם שיקרא גם כן בכור הגם שהוא ב' וג' לבטן זולת הוא היוצר הוא הבורא ברוך הוא מכיר הטיפות שצר מי ומי הבכור:
@34 **ומת כל בכור**. ולא אמר והרגתי כל וגו' להיות כי ה' ברוך הוא פועל הטוב כידו אבל פעולת הרע יצו למשרתיו עושי דברו והם יעשו, לזה לא אמר והרגתי אלא ומת פירוש על ידי שליח, ומעשה ה', המה הזכרת הודעת הבכורות זה הוא וזה גורם כי המשחית ישחיתנו ' ומת, ומזה יתגלה פירוש אומרו והכיתי שהוא על ידי שליח:
@34 **עוד** ירצה על דרך אומרם ז''ל (שבת ל''ד.) יהב ביה עיניה וקטליה, גם אמרו ונעשה גל של עצמות. והנה דברים אלו בהשקפה ראשונה ירחקם השכל כי איך תהיה ראיית צדיק לרעה והלא כתיב (משלי כ''ב) טוב עין הוא יבורך, גם ציין ר' שמעון בן יוחאי ז''ל (זהר ח''ג רי''א) לרע עין המזיק בעינו כי הוא חלק רע. אכן אחר ההשקפה בדקדוק אומרם יהיב עיניה היה לו לומר ראה בו בעיניו, אלא להיות כי כל חלק רע שבעולם בהכרח כי יהיה לו דבר המעמיד כל שהוא מהחיוני שהוא בחינת הטוב כי חלק הרע שם מיתה יש לו ואיך יחיה ויהיה במציאות ואין צריך לומר שיתנועע וילך כבעלי חיים, לזה בהכרח שיהיה בו חלק כל שהוא מבחינה הנקראת חיים וזה חלק טוב. ובזה תשכיל להבין מאמרם ז''ל (סוכה נ''ב.) כי לעתיד לבא יביא הקדוש ברוך הוא לס''מ וישחטנו במעמד הצדיקים וכו' עד כאן. ודברים אלו אין להם משמעות כי לא יוצדק שחיטה למלאך, ולמה שהקדמנו תהיה הכוונה כי יסיר ממנו חלק המחייהו ובהסרת ממנו חלק הטוב זו היא שחיטתו:
@34 **עוד** יש לך לדעת כי כל מקור ישאף למינו וישאבנו, וזה הוא סוד בחינת בירורי ניצוצי הקדושה באמצעות נשמות ישראל ועסק תורתם, והצדיקים העצומים קדמונינו יכירו בהביטם באדם רשע לברר ממנו כח החיוני שהוא בחינת הטוב באמצעות הראיה הדקה אשר יביטו בעין החכמה להוציא חלק הטוב ההוא כי כשיתכוין למול ענף הקדושה תעשה בו נפש הצדיק כמעשה אבן השואבת לברזל הנקראת קאלמיט''ע בלע''ז שתוציאנו ממקום שנקבע שם בראיה, וה' עשה דמיונות בעולם להאמין אדם בתורת חכם. ומעתה נמצא דעת אלהים באומרו ומת כל בכור פירוש כי באמצעות שאני עובר בתוך מצרים בזה ימות מעצמו כל בכור כנתינת עין של חכמים ברשעים ועושים אותם גל של עצמות כי באמצעות כן יצא מהם החיוניות כמו כן הדבר הזה שיפריד מהם באמצעות העברתו שם כל נשמות הבכורות והבן הדברים. ואומרו **כל בכור** פירוש לא שתצא הנפש מהגוף לבד אלא שגם בחינת נפש תמות גוף ונפש של קליפת בכור מצרים. ואולי כי בזה לא נתעצם שום גלות עוד כבחינת גלות ושעבוד מצרים כי אבד כח הקליפה העצום שהוא בחינת בכור:
@34 **וראיתי** לתת טעם למה לא יצאו ישראל אלא באמצעות מכת בכורות. עוד למה ה' הכה אפילו בכור שאינו מצרי דכתיב (לקמן י''ב כ''ט) בכור השבי. ואולי כי הטעם הוא לצד שמצינו שקרא ה' לישראל (לעיל ד' כ''ב) בני בכורי וכבר הודיענו רבותינו ז''ל (זהר ח''ב רס''ג) כי כל מה שברא ה' במדת הטוב גם זה לעומת זה עשה האלהים בבחינת הרע וכל בחינה ובחינה שיש בקדושה יש כנגדה בקליפה והקליפה מתאמצת ומתחזקת לאחוז בה, ולזה כנגד בחינת הבכורה שבקדושה היתה בחינת בכורה שבקליפה אוחזת ותוקפת בה לבל שלח עד אשר הרג ה' כל שם הבכורה שבקליפת מצרים בין של מצרים בין של האומות שהיו שם דכתיב עד בכור השבי ובכור השפחה וכל בכור בהמה, וגם בכור ישראל קדש אותם ה' כאומרו (במדבר ח' י''ז) כל בכור וגו' הקדשתי אותם לי כדי שלא תשאר בכורה זולת של קודש אשר הקדיש ה', ולזה מת אפילו בכור בהמה, וכיון שנעקר שם זה נפל ענף הרע שהיה מחזיק בבכור הקדושה ולזה תכף יצאו בני ישראל והגם שמצינו שיצאו ורדפו אחריהם, חשבו שעדיין יש בהם כח לאחוז בם, וצא ולמד מה עלתה בידם לא נותר בהם עד אחד:
@36 **ולכל בני ישראל וגו'**. צריך לדעת הכוונה בזה, ואם לומר שלא ימות אדם מהם, היה לו לומר בפירוש ולא ימות מבני ישראל וגו'. ואולי שנתכוין בסדר הדיבור על דרך אומרם ז''ל (בבא קמא ס:) כלבים צועקים מלאך המות בעיר, לזה אמר **ולכל בני ישראל** וגו' כדי שתדע שלא ימות מהם אדם שלא יחרץ כלב לשונו שם הא למדת שלא נראה ביניהם מחבל, והוא אומרו **למען תדעון אשר יפלה**:
@36 **עוד** נתכוון לרמוז לו כי דוקא במקום שיהיו כל בני ישראל פירוש כולם יחד יהיו ישראל לא יחרץ כלב וגו' זה לך האות כי אין זר אתם אבל אם לא יהיו כולם בני ישראל ויהיה ביניהם איש מצרי יחרץ כלב לשונו הא למדת כי יראה שם משחית, והכוונה בזה לומר לו כי לא תועיל ערמה לבכורות להמלט שהגם שיתחבאו הבכורות המצרים בין ישראל לא ימלטו באמצעות זה, וכן אמרו רז''ל (שמות רבה פי''ח:) (ח) **וירדו כל עבדיך וגו'**. כאן הבטיח כי עבדיו אלו יחיו ולא ימות מהם אחד במכת בכורות. ואולי שהיו כולם פשוטים ואין בכור ביניהם וידע בידיעת נביא. או הגם שהיו ביניהם בכורות אף על פי כן הוציאם מכלל המכה, והטעם לא לצד צדקותם אלא לצד שביזהו פרעה הרשע בפניהם ודבר אליו כדבר הנבל אל תוסף ראות וגו' כי ביום וגו' לזה צריך גם הוא להתבזות בפניהם כדין המבייש חבירו בפני רבים שצריך לפייסו בפניהם, ותמצא שהקפיד משה על הדבר דכתיב ויצא מעם פרעה בחרי אף. והנה הגם שלא אמר משה אלא וירדו כל עבדיך נתכוון לומר גם עליו כי הוא בעצמו יקום לילה אלא שדבר דרך כבוד:
@36 **והשתחוו לי לאמר**. טעם שלא אמר בפירוש ויאמרו לי, נתכוון לומר כי אמצעות ההשתחויה עצמה יגיד כי כוונתם לאמר צא אתה כיון שהוא אדון עליהם אם כן האדון יעשה חפצו ואין עליו שלטון. עוד ירצה כי להיות כי מנהג המלכים כשיבא אדם לדבר אליהם דבר ישתחוו לפניו ומזה ידע המלך כי הם חפצים לדבר עמו, כי אין מהמוסר לדבר לפני מלך גדול בלא שאלת רשיון גם אין דרך כבוד לשאול רשות לזה ישתחוה ובזה ידע המלך כי חפץ דבר ויאמר אליו דבר, והוא שאמר **והשתחוו לי לאמר** פירוש שההשתחויה היא להגיד שרוצים לאמר והאמירה צא אתה וגו'. והגם שלא הזכיר הכתוב פרט זה באותה הלילה, קצר ואמר גדולה מהאמור כאן שפרעה עצמו קם לילה וגו':
@38 **ויאמר ה' וגו** ' **לא ישמע**. הכוונה בזה אולי שחשב משה כי פרעה בראותו כל המופתים והפלאים אשר עשה משה בזה הגם שיראה כי הלכו ישראל ולא חזרו שמא תפול עליו אימתה ופחד ולא ירדוף אחרי בני ישראל, לזה הודיעו כי לא ישמע פירוש לא יקבל אליכם פירוש למה שאתם חושבים שהחליט דעתו מישראל. ואמר לשון עתיד לומר אפילו אחר מכת בכורות לא אכניע לבו לקצה האחרון לקבל לשלוח בהחלט, והטעם למען רבות מופתי בארץ מצרים כשירדפו אחריהם, ואומרו ארץ כבר אמרו ז''ל (מכילתא י''ד) בפסוק כי ה' נלחם להם במצרים וגו' יעויין שם דבריו:
@38 **עוד** ירצה להיות שאמר משה **והשתחוו לי לאמר צא אתה וכל העם אשר ברגליך** ופירוש ברגליך הוא ברשותך, הרי שהוציאם לעם מרשות פרעה ונתנם ברשות משה רועינו מלכינו ובזה גילה לו כי יציאתן ממצרים היתה בעקירת רשות פרעה מעליהם לזה אמר ה' אליו **לא ישמע אליכם פרעה** פירוש לא יבין דבריכם פרעה, והטעם למען רבות מופתי, ואם יבין הדבר מעת שיאמר לכם בלילה (י''ב ל''א) קומו צאו יחליט הדבר ואין לו מקום לרדוף אחריהם אחר כך ואין מקום למופתים שאני רוצה להרבות מאתים וחמשים מכות יסובבוהו:
@39 **ומשה ואהרן וגו' ויחזק וגו** '. כוונת הכתוב לומר שהגם שעשו את כל המופתים האלה אף על פי כן לא נתרצה לשלחם אפילו שלא בהחלט אלא לצאת מארצו לבד כאומרו (לעיל ה' ג') נלכה נא דרך ג' ימים:
@41 **החדש הזה לכם וגו'**. טעם כפל ראש חדשים ראשון הוא וגו', נתכוון לומר כי חדש זה הוא ראש פירוש מובחר שבחדשים על דרך או' (שמות ל') בשמים ראש. ודקדק לומר **לכם** כי אינו משובח ומעולה שבחדשים אלא לישראל. ותמצא שאמרו רבותינו ז''ל (ראש השנה י''א.) בניסן נגאלו בניסן עתידין ליגאל, כי החודש מסויים לטובת ישראל ועל זה ראשון הוא ראוי להיות לכם שיהיו מונים מניסן לצד מעלתו. עוד ירמוז באומרו **החודש הזה** ולא אמר חדש זה, לרמוז על הידוע שהוא הקדוש ברוך הוא דכתיב (לקמן ט''ו ב') זה אלי כי יהיה זה לכם שיגלה להם כאומרם ז''ל (מכילתא י''ד) ראתה שפחה על הים וכו'. עוד ירמוז **כי החדש הזה לכם ראש** פירוש שיהיה לישראל כינוי בחינת הראש שלא יהיו עוד נבזים ושפלים. עוד רמז בתיבת זה כי יהיה ראש לכל החדשים שהם י''ב כמספר זה:
@42 **דברו וגו' לאמר**. צריך לדעת למה הוצרך לומר דברו ולא סמך על מה שאמר בפסוק ראשון ויאמר ה' וגו' לאמר, ואם לא הספיק לו תיבת לאמר היה לו לומר דברו קודם אומרו החדש הזה כי מצוה זו לישראל לדורותם נתנה ולמה לא אמר קודם לה דברו. עוד קשה אומרו תיבת **לאמר** כי למי יאמרו ישראל. ואולי כי לצד שבמצוה זו של לקיחת השה יש בה ב' בחינות, א' לטובה כי בה נשאו ראש וראו אותם אויביהם עושים באלהיהם שפטים כאומרם ז''ל (שמות רבה פט''ז), והב' לצד המצוה כי מצות המלך היא לעשות כן והעובר עליו ענוש יענש לזה הוצרך לומר **דברו** וגו' **לאמר**, דברו לשון קושי כנגד צורך הדבר וגזירת מלך ולהעניש על כל עובר, ולאמר אמירה רכה כנגד מעלה וכבוד אשר תשיגם בדבר. ולצד שבמצוה שצוה בתחלת הנבואה שהיא לחשוב מניסן אין עונש לעובר על זה כעונש החודל מעשות הפסח ולזה לא אמר כנגדה אלא לאמר אשר על כן הוצרך לחזור ולומר דברו כנגד מצות פסח, ואמר עוד לאמר כי גם בה יש מעלה לישראל כנזכר. ובדרך דרש צום להנהיג את ישראל בהנהגת התורה והמצות להודיעם חוקי ה' ותורותיו ולהנהיגם בדרך ישרה, ולזה אמר דברו ואמר לאמר פירוש כדי שיהיו מעולים, על דרך אומרו (ישעי' ג') אמרו צדיק וגו':
@42 **עוד** ירצה כי מתחלה ידבר אל הזקנים כמו שמצינו לו שכן עשה משה דכתיב (פסוק כ''א) ויקרא משה לכל זקני ישראל, והוא אומרו **דברו אל כל עדת ישראל**; **לאמר** שיאמר להעם, והוא גם כן מה שאמר שם הכתוב ויאמר אליהם:
@42 **ויקחו להם וגו'**. קשה למה אמר ו' בתחלת ענין. ואולי כי רמז לדברים הנאמרים בדברי משה לישראל דכתיב משכו וקחו וגו' ואמרו רבותינו ז''ל (שמות רבה שם) משכו ידיכם מעבודה זרה וגו', ודבר זה לא נאמר בדברי ה' והנה מדברי משה נשמע כי כן נאמר לו בנבואה, והוא אומרו ויקחו בתוס' ו' רמז שקדם דיבור ומה הוא משכו שאמר משה. עוד ירצה להיות שאמר בעשור יכול לקח בעשור ישחט לא לקח בעשור לא יקח בי''א בי''ב בי''ג, תלמוד לומר ויקחו לרבות אחר כך ובמכילתא (כאן) למדו דין זה של לקיחה בי''א בי''ב בי''ג מדין קל וחומר ודבר הבא בקל וחומר אם נמצא לו רמז בכתוב נסכים לומר כי לזה נתכוון. עוד ירמוז בדקדוק עוד תיבת להם. עוד אומרו תיבת **איש** שלא היה צריך לומר אלא ויקחו שה לבית וגו', אכן ירצה על דרך אומרים ז''ל (תנחומא) בפסוק ויקחו לי תרומה וזה לשונו אמר הקב''ה קחו אותי עמכם, והוא אומרו כאן לצד כי זו מצוה ראשונה הודיעם השגת המצוה כי בעשותה ישרה עליו ה' שכינתו בסוד (דברים כ''ח י') וראו כל עמי הארץ כי שם ה' נקרא עליך, גם אמרו כי תיבת מצוה יש בה שם הוי''ה חצי בא''ת ב''ש וחצי בפשוט (תיקוני זוהר תיקון כ''ט) והוא אומרו **ויקחו להם איש** פירוש על דרך אומרם ז''ל (סוטה כ''ט מ''ב:) איש אין איש אלא הקב''ה, כי במצוה זו יקחו להם לקיחה גדולה ועצומה והוא איש שהוא אלהינו מלכנו:
@42 **וראיתי** לתת לב למה לא צוה ה' בפסח מצרים על הטמאים והערלים ובני הנכר שלא יאכלו מפסח, הן אמת כי אזהרת הטמאים לפי מה שכתבנו בפרשה זאת חקת התורה יש טעם נכון בדבר, אבל הערלים ובני הנכר למה לא צוה אותם ה'. והנה לפי דבריהם ז''ל הוזהרו ישראל על שניהם על המילה כאמור בדברי קבלה (יחזקאל ט''ז) ואראך מתבוססת בדמיך, ואמרו רבותינו ז''ל (שמות רבה י''ט) דם פסח ודם מילה, ועל בן נכר דרשו רז''ל (שם ט''ז) בפסוק משכו וגו' משכו ידיכם מע''ז הרי שהזהיר על הדבר כי קודם מצות הפסח יצאו מכלל עובדי עבודה זרה ויכנסו בכלל ישראל, וכל זה אינו מספיק לקושייתינו כי למה לא באו הדברים בדברי ה' בעיקר המצוה:
@42 **והנה** בסוף הפרשה אחר שסדר יציאת ישראל ממצרים נאמרה פרשת זאת חקת הפסח וגו' כל בן נכר וגו' וכל עבד וגו'. וראיתי לר' אברהם בן עזרא ז''ל שכתב כי פרשה זו נאמרה לפסח דורות והוסיף מצות אחרות וכו', ואם נתכוין לומר כי בן נכר וערל הם מצות מוספות בפסח דורות דבריו כאן בטלים הם כפי דברי רבותינו ז''ל, וגם ממה שגמר אומר הכתוב שם בפרשת ערל ובן נכר ואמר (פסוק נ') ויעשו בני ישראל כאשר וגו', ואם לפסח דורות נאמרה פרשה זו לא היה לו לומר ויעשו בני ישראל כאשר צוה וגו' שמשמע שעשו ישראל כל האמור בפרשה, גם מה שאמר שיכוין על פסח שעשו במדבר סיני הם דברים בעלמא ומי ישמע אליו ואין צריך לומר לקבל דבריו בזה, הגם שהרב ז''ל חש לקמחיה ואינו חולק על דברי רבותינו אלא בדבר שאין בו הוראה לעתיד אף על פי כן גם במה שלפנינו חולק בלא עומק המכריח וכיוצא בו:
@42 **וראיתי** לרבותינו ז''ל במכילתא שאמרו וזה לשונם זאת חקת הפסח בפסח מצרים ובפסח דורות הכתוב מדבר דברי רבי יאשיה רבי יונתן אומר בפסח מצרים הכתוב, מדבר אין לי אלא פסח מצרים פסח דורות מנין תלמוד לומר ככל חוקותיו וגו' יעשו אותו על כרחם, הרי דלכל דעת התנאים בפסח מצרים הכתוב מדבר ונעקרו דברי ר' אברהם בן עזרא והיו כלא היו, ולפי זה אפשר שירמוז הכתוב באמרו **ויקחו** פירוש מלבד מצות מילה ומצות משיכתם מעבודה זרה שהוא בחינת בן נכר שצוה ה' הוסיף. עוד לומר ויקחו וגו', ואומרו **להם** כאן רמז שלילת בן נכר וערל שלא יוכלו לאכול בפסח כמו שבא הדבר מבואר בנבואת זאת חקת הפסח:
@43 **ואם ימעט וגו'**. הכתוב יתיישב בין לדעת ר' יהודה ובין לדעת ר' יוסי שנחלקו בתורת כהנים (מכילתא, פסחים צ''ט.) לרבי יהודה שאמר צריך שישאר אחד מבני חבורה ראשונה ידוייק אומרו **ימעט הבית** פירוש שיתמעט. מהחבורה ולא כל החבורה, ולרבי יוסי שאמר שלא יניחו הפסח כמות שהוא ידוייק אומרו **מהיות משה** שמעט שה יתמעט ממנויים ועליו הוא ההקפדה שלא ישאר בלא מנויים, והכתוב שקול הוא:
@43 **עוד** נראה שיכוון לומר שאין דרך שיהיה השה מועט לאוכליו כי כזית בשר ימצא בו לרבים שיהיו בחבורה:
@43 **או** ירצה כי ברכת הקודש מרובה הוא וימצא בו שיעור הצריך למנוייו ולא ימצא המיעוט אלא בבית שהם בני חבורה שלא יספיקו לאוכלו:
@43 **לפי אכלו תכוסו**. יתבאר על דרך אומרם ז''ל (פסחים פ''ח.) שוחט אדם על ידי בנו ובתו הקטנים וגם על ידי אשתו, גם אמרו (שם פ''ז:) אם היא למודה לבא אצל אביה אוכלת משל אביה לצד היותה רגילה לאכול שם, והוא אומרו **איש לפי אכל**. ו פירוש על אותם שהם רגילים לבא אצלו לאכול וסומכים על שלחנו לפי מה שהם ימנה עמו ושם קנו מקומם:
@43 **עוד** יתבאר על דרך אומרם (שם צ':) שאונן שוחטין עליו הגם שבשעת שחיטה אינו ראוי כיון שיכול לאכול בלילה שוחטין עליו, והוא אומרו **לפי אכלו** פירוש הולכין ונמנין בשעת שחיטה על שעת אכילה:
@43 **עוד** ירצה **לפי אכלו** על פי מה ששנינו בפסחים (שם) זב וכו' שוחטים עליו וגם אמרינן התם שוחטין וזורקין על טבול יום ומחוסר כיפורים ועולא אמר אף על טמא שרץ עד כאן, והטעם הוא כל שיכול לאכול את פסחו בעת אכילתו, והוא אומרו **לפי אכלו** פירוש אין הולכים בו אלא לפי אכילתו של פסח וכל שבשעת אכילתו הוא ראוי לאוכלו הגם שבשעת שחיטה לא היה ראוי שוחטין עליו, ולפי זה הוא הדין טמא מת אם היה יום ז' שלו חל ביום י''ד שוחטין עליו ואוכל לערב:
@43 **ומה** שאמרו שם בתורת כהנים והובא בפסחים דף צ' סברת תנא שסובר כי ולא יכלו לעשות הפסח ביום ההוא (במדכר ט' ו') יום ז' שלהם היה ואף על פי כן נדחו לפסח ב', דוקא טומאת מת דחמירא ולזה אמר (שם) לנפש אדם הגם שלערב היו טהורים. ולר' יוסי הגלילי (שם) נוכל לומר שאפילו טמא מת שחל ז' שלו ביום י''ד שוחטים עליו. ומה גם אם טבלו וכדעת התוספות בפסחים דף צ' ולדעת הראב''ד שהשיג על רמב''ם בפ''ו מהלכות קרבן פסח יעויין שם דבריו והוא היותר קרוב לפשטא דסוגיא:
@44 **ומן העזים תקחו**. טעם שהוצרך לומר **תקחו** לומר אפילו יש כבשים יכול ליקח מן העזים, לזה סמך לקיחה לעזים:
@45 **והיה לכם למשמרת**. פירוש צריך שמירה כדין קדשים כיון שקרא עליו שם פסח. עוד ירמוז על דרך אומרם ז''ל (שיד השירים רבה פ' כשושנה בין החוחים) בפסוק גוי מקרב גוי שהיו ישראל במצרים סרוכים קצת בחוקי עבודה זרה מצד היותם בין המצריים, ואמרו עוד (שמות רבה פט''ז) שרמז הכתוב באומרו משכו שימשכו מעבודה זרה. והנה אין כוונתם ז''ל לומר חס ושלום שהיו עובדי עבודה זרה אלא לצד שהיו ביניהם מבלי ידיעתם יעשו חוקים של עובדי עבודה זרה בפרטי המלבושים והמאכלים ודברים הרגילים, ואשר על כן מלבד שצוה שיעקרו מאותם פרטים שידמו להם נתחכם עוד אל עליון לעקור בחינת הרע מהם ולעשות תיקון עון זה ואמר שיקחו הטלה שהיא עבודה זרה של מצרים שבה היה לישראל המכשולות ויעשו בה מצוה האמורה בענין ובזה יהיה להם תיקון לשמירת עון עבודה זרה, והוא אומרו **והיה לכם למשמרת** פירוש במקום מצות שמירת עבודה זרה כשינהגו בו משפט כתוב והבן:
@47 **ואכלו את הבשר**. רבותינו ז''ל (פסחים פ''ג.) אמרו את הבשר ולא גידים ועצמות קרנים וטלפים. ולדבריהם למה אמר את מה בא לרבות. ונראה כי בא לרבות מה שאמרו במשנה (שם פ''ד.) כל הנאכל בשור הגדול נאכל בגדי הרך, ומפרש לה רבא כל הנאכל בשור הגדול בשלקא וכו':
@47 **עוד** ירצה על פי מחלוקת ר' יוחנן ודיש לקיש (שם) בגידין שסופם להתקשות לר' יוחנן נמנין ולריש לקיש אין נמנין. לר' יוחנן יתבאר הכתוב על זה הדרך את הבשר כל שדמו לבשר שעמהם קאמר והרי הם דומין, ולריש לקיש כל שדומין לבשר בבחינת הבשר מצד עצמו וכשם שהבשר אין סופו להתקשות וכו':
@47 **ומצות על מרורים**. לפי פשט הכתוב לפי מה שראינו שאמר ה' שצריך צלי אש ושיהיה שלם כו' זה יגיד שדעת עליון הוא להראות בחינה הגדולה והחירות ואין רשות אחרים עליהם, ולפי זה גם המרורים שיצו ה' הוא לצד כי כן דרך אוכלי צלי לאכול עמו דבר חד כי בזה יערב לחיך האוכל ויאכל בכל אות נפשו. גם בזה יוכר גודל העריבות כשיקדים לפיו מרורים. גם מה שהזכיר המצות הוא פרט אשר יכונן חיך אוכל יטעם לו הצלי. והנה ג' השריגים יטעימו יחד והוא רומז לג' דברים, הא' הוא הגלות שמררו את חייהם, הב' היא היציאה תיכף ומיד שלא הספיק בצקם להחמיץ במצרים, ג' אשר פסח ה' על בתיהם והוא בחינת הגאולה כי עבר ה' בארץ מצרים ונתק חבל מוסרות העבות שהיו תוקפים בהם שהוא בחינת הבכורה וכמו שפירשתי הענין במקומו (לעיל י''א ה'). ושלשת הענינים יחד היו צריכין להיות וזולת א' אין נס בשנים האחרים, שאם לא היה הגלות לא היו משיגים אשר השיגו מהצירוף ומה שבררו, ומה גם לפי מה שכתבנו במקומות אחרים (ויגש מו ג) כי גוי גדול עצמו שהוציא ה' ממצרים הם בחינות ניצוצי הקדושה ששם היתה ושם נמצאת, וסגולת הוצאתה הוא המרור אשר מררו את חייהם, והוא סוד אומרו (קהלת ח') עת אשר שלט האדם באדם לרע לו. ואילו לא היה המהירות שהוציאם ה' היו חוזרים ומשתקעים בוררים ומתבררים, והוא מאמר התנא (הגדה) ואלו לא הוציא וכו' עדיין וכו' והיינו עבדים לפרעה וכו' דכתיב (לקמן יב לט) ולא יכלו להתמהמה, ועיקר הגאולה היא הפסיחה. נמצאת אומר כי שלשתם יחד הם העיקר, ולזה היה הלל מדקדק לכורכם יחד (פסחים קט''ו.):
@52 **ולא יהיה וגו' למשחית**. פירוש לסיבת משחית שיוצא להשחית בזולת אין בו אלא בחינת טבע ההשחתה לכל זולת בראות חותם שמו יתב' שהוא המצוה יפחד וירא מגשת אליו, לזה הוא שצוה ה' להיות הדם לאות. ואם תאמר אם כן מצרי שהיה נחבא אל בית ישראל יהיה ניצול תלמוד לומר בכם ולא במצרים כי לא תאיר אור המצוה להצלה אלא על ישראל דכתיב (ישעי' ס') ועליך יזרח ה' וכבודו עליך יראה:
@53 **חקת עולם תחגוהו**. טעם שלא הספיק לומר לדורותיכם. והגם שאמרו ז''ל (מכילתא) כי דורותיכם לבד הייתי אומר מיעוט רבים שנים תלמוד לומר חקת עולם לגלות על פירוש דורותיכם שהוא תמיד עדיין קשה לא היה לו לומר לדורותיכם אלא חקת עולם. אכן יתבאר על דרך האומר (ברכות י''ב:) למען תזכור את יום צאתך מארץ מצרים כל ימי חייך להביא לימות המשיח, ולמאן דאמר כל ימי חייך הלילות אפשר כי אמר חקת עולם שלא תאמר תינח בימי החירות בימי הגלות שאנו משועבדים מה מקום לזכרון לטובה שפסקה תלמוד לומר חקת עולם אפילו בזמן השעבוד בשאר גליות חקה חקק ה'. ומאמצעות פירושם זה תשכיל גם כן הסרת טענת לדורותיכם שאין כוונתו ב' דורות. ואם לא היה אומר לדורותיכם לא היינו שומעים מה שפירשנו בחקת עולם והיינו אומרים שלא בא אלא להתמדת דורות ולא לב' דורות לבד הנשמע מתיבת לדורותיכם ומהייתור שמענו מה שפירשנו:
@54 **שבעת ימים**. הנה הטעם הוא לצד שלא הספיק בצקם להחמיץ וגאלם הגואל. ואם תאמר והלא היוצאים עדיין לא יצאו לעשות זכרון לדבר. הלא גם הפסח שצוה ה' לקחת שה לבית אבות וגו' עדיין לא פסח אלא שבזכות מצוה זו יפסח ה', גם המצה בזכות מצוה זו ימהר לגואלם, וכן היה:
@54 **ותמצא** שאמרו רבותינו ז''ל (פסחים ק''כ.) מדרשות התורה בא' בי''ג מדות כי כל שבעה אין חיוב במצה אלא לילה הראשונה קבעו הכתוב חובה, והטעם כי גם בחינת המצוה לא היה אלא בליל ט''ו וזה נקבע לחובה בזמן עצמו ומאז והלאה אין כיוון בנס למצוה והבן. וטעם אומרו שבעת ימים מצות אינו אלא רשות. ואולי שדיבר בסדר זה לומר כי מעלה עליו הכתוב כאלו אכל כל ז'. ותמצא כי צוה ה' ב' מקראי קודש ביום הא' וביום הז' יום א' לצד נם יום ט''ו, ויום ז' לצד נם גמר הגאולה של קריעת ים סוף וכו'. עוד טעם אומרו **שבעת** לצד שלא צוה ה' בכל ז' לאו דלא תאכל חמץ והייתי אומר אם לא אכל חמץ אין בידו לא זכות ולא עונש תלמוד לומר שבעת ימים תאכל מצות לומר לך כי כשלא אכל חמץ כאלו אכל מצות והרי בידו ז' מצות עשה. וטעם ז' ולא פחות ולא יותר, נתכוון ה' שיהיו עסוקים במצות עד גמר הגאולה שהוא ביום ז' של פסח אשר הפליא ה' עשות נסים להם וברודפיהם משפטים. גם יש טעם ברוחניות כי יסודי הקדושה שהם שורש נשמות ישראל שבעה עינים (זכרי' ג), ותקרא כנסת ישראל בת שבע לסיבה זו (זהר ח''ג ו':) (יז) **ושמרתם את המצות וגו'**. פי' כשם שאני שמרתי היום ולא אחרתי יום אחד ובעצם היום הזה הוצאתי אתכם לטעם זה אתם גם כן לא תאחרו המצה עד שתחמיץ. ואמר עוד **ושמרתם את היום הזה** יצו כן האל גם כן שיהיה האדם משמר גם היום לבל יטעה בחשבון ולא יקדים ולא יאחר מעשות את היום הזה ולא יום אחר במקומו. וכל פי' זה אומ' **כי בעצם** יאיר ימין ושמאל, יאיר לתת טעם למה שלפניו לשמידת המצות, ויאיר למה שלאחריו לשמירת היום על זה הדרך כי בעצם וגו' פירוש לטעם שבעצם היום וגו' ושמרתם אתם גם כן את היום הזה:
@60 **ויקרא משה לכל זקני ישראל**. והגם כי ה' אמר אליו דברו אל כל עדת ישראל, יהיה פירושו כמאמר (ויקרא ד' י''ג) ואם כל עדת ישראל ישגו שיאמר על הזקנים כמו שמפורש במקומו (בתורת כהנים), ויאמר אליהם יכוין לשאר העם כמשפט כל מצות ה' לישראל שהיו מפי משה (עירובין נד.):
@60 **או** אפשר שלא אמר אלא לזקנים והם ידברו לכל עדת ישראל, וחלוקה מצוה זו משאר מצות התורה כי עדיין לא נכנסו ישראל בברית ולא הוחנכו להכנם לשמור ולעשות ולזה היה מדבר לזקנים והזקנים כל א' ידבר בנחת ובדרך המתקבל לבני משפחתו כדי שיהיו נוחים לעשות:
@63 **ושמרתם את הדבר הזה**. הנה פשט הכתוב יגיד כי גם לדורות יצו דברים האמורים בענין ולא ראינו שעשו כן קדמונינו, גם רבותינו לא צוו לעשות כן. ונראה כי ממה שאמר הכתוב **לחק לך** בפני עצמו וחזר לומר **ולבניך** גילה המכוון שהוא על זה הדרך שאין הדברים שוים בו ובבנו שהיה לו לומר ושמרתם את הדבר הזה לחק עולם, ומאומרו לחק לך ולבניך הרי זה מפרש המכוון שאינם שוים בדבר, לחק לך הוא כל האמור בענין. ולבניך עד עולם פרטים מהענין, וסמך הכתוב על שיבא במקומות אחרים הפרטים שהם נוהגים לדורות ושלל בהם פרטים שאינם לדורות שלא הזכירם בהם, וגם כאן ביאר הדברים באומרו ולא יתן המשחית לבא אל בתיכם לנגוף שינגוף את מצרים ודבר זה אינו מצוי לדורות:
@64 **והיה כי תבואו וגו'**. הנה פשט הכתוב יגיד כי מצוה זו אינה אלא אחר כניסתם לארץ, אם כן למה חזר ה' מדעת זו וצוה את בני ישראל (במדבד ט א) בשנה השנית לעשות הפסח במועדו ככל חקותיו:
@64 **ונראה** כי גילה ה' דעת עליון בזה כי היה בדעתו אם יזכו ישראל לא יעשו פסח ב' אלא בארץ כנען אלא לצד המראתם מעת יצאו ממצרים והם ממרים פי ה' ואפילו בים סוף התחילו למרות דכתיב (תהלים ק''ו) וימרו על ים בים סוף זה היה סיבה שארכו הימים ולא היה להם זכות לעלות תיכף ומיד, ולזה כשראה ה' שגרמו מעשיהם ולא נכנסו לארץ והם עדיין במדבר הוצרך לצוות לעשות הפסח במדבר כי עד עתה לא נצטוו אלא כי תבואו אל הארץ. והגם כי האדון קורא הדורות מראש (ישעי' מ''א), אף על פי כן מחשבותיו הטובים הגיד לעמו כנזכר:
@67 **וילכו וגו' כן עשו**. הוצרך לומר **כז עשו** ולא הספיק במה שקדם לומר ויעשו וגו', לומר הצדיקו במעשיהם במצות ה' ולא הבינו דבר שלא כן הוא במשמעות, וזה לא היה נשמע מאומרו ויעשו וגו' כאשר וגו' כי אפשר שהכתוב אומר מה שחשבו הם והבן:
@69 **ויקם פרעה לילה**. טעם אומרו **לילה** יתבאר על ררך אומרם ז''ל (זהר ח''ב ל''ח.) כי אותו לילה היה כיום יאיר כצחות היום. ורמזתי רמז זה בפסוק (לקמן יג ח) והגדת לבנך ביום ההוא כי יכוין לומר שיגיד לו גם נס הלילה שנעשה יום. ושמא תאמר כי זרח אור בלילה דרך כלל לרעים ולטובים. לזה אמר **ויקם פרעה ליל**. ה כשקם הוא לקרוא למשה ולאהרן מנע ה' מרשע אורה והיה לילה פירוש חשך כאומרו (בראשית א ה) ולחשך קרא לילה:
@70 **ויקרא למשה וגו' לילה**. טעם אומרו פעם ב' **לילה**;. אולי להיות כי חש פרעה בקריאתו למשה שלא יצא לקראתו מחשש גזירתו שאמר לו (לעיל י כח) אל תוסף ראות פני כי ביום ראותך פני תמות ואם כן יחוש לבל יעליל עליו, לזה אמר בקריאתו לילה פירוש אין זה מתנאי הגזירה כי הוא לא אמר אלא ביום ולא בלילה וזמן זה לילה הוא. או לצד שלא יראה פניו הוא אומר כי הוא לילה ואין כאן טענת אל תוסף ראות פני כי הוא במחשך לא יראו איש את וגו':
@70 **או** יכוין הכתוב לומר תשובת משה אל פרעה כשקרא לו כי ענהו ואמר לו לילה ואין אני יכול לצאת לדבר עמך כי צוה ה' (פסוק כב) לא תצאו איש מפתח ביתו עד בוקר, ואמר פרעה **קומו צאו** וגו' פירוש עשאם בני חורין לעצמן, ואולי שרמז בתיבת **קומו** לשון התקוממות ונשיאות ראש על דרך מה שדרשו רבותינו ז''ל (כ''ר פג''ח) בפ' (כראשית כג) ויקם שדה עפרון, וחשב כי בזה תקל המכה מעליו כשיגמור הדבר מצידו לשלחם הגם שיבא העיכוב מהם אין עליו אשמת דבר:
@70 **עוד** ירמוז באומרו **קומו צאו** כי לצד שלא היו רוצים לצאת אליו קראם לקום כי חשב שאינם רוצים לקום ממטתם לבוא אצלו ואמר כי קריאתו להם הוא להנאתם שאומר להם צאו וגו'. ולדרך זה טעם אומרו לילה, הקדים הכתוב לומר טעם שלא יצאו לקראתו תיכף ומיד וה' צוה על כבוד המלכות לזה הקדים סיבה אשר סבבה עכבתם מצאת ואמר לילה וזו סיבה שלא קמו ויצאו אצלו כי ה' צוה לא תצאו איש מפתח ביתו וגו':
@70 **גם אתם וגו'**. צריך לדעת למה אמר גם בתחלת דבר. ועוד וכי משה ואהרן היו אסורים שהוצרך לומר צאו מתוך עמי. ואולי כי מתוך דבריו גילה מחשבתו כי היה חפץ שיוצגו משה ואהרן לזה אמר **גם אתם** מלבד ישראל, ולצד שאין הדבר מובן בתיבת גם שהיא על ישראל כי לפי האמת משה לא היה במאסר וכשאמר גם אין במשמעות הקודם בני ישראל ולא יוצדק לומר גם אתם אלא לפי מחשבת פרעה כנזכר, לזה חזר לבאר **גם בני ישראל**:
@70 **עוד** ירצה כי נתכוון לגרש אותם הגם שיחפצו מרצונם לשבת עמהם, ולפי זה יוצדק לומר **גם אתם** הגם שאתם ברשות עצמכם אף על פי כן אין אני חפץ שתשבו בארצי, וזה חידוש, והוא מה שאמר ה' (י''א א') כשלחו כלה גרש יגרש אתכם. ואומרו **גם בני ישראל** לרבות הטף והנשים, ואומרו **גם צאנכם** וגו' לרכות שאר מקנה או לרבות מה ששאלו לעזר ממנו:
@71 **וברכתם גם אותי**. כאלו אמר וגם תברכו אותי, ושיעור הכתוב וברבתם גם כן אותי מלבד שיסיר המכה הרחקת הנזק והקרבת התועלת:
@74 **עשו כדבר משה**. פירוש לא להנאת הממון אלא למצות נביא. עוד ירצה על פי מה שהעלה רמב''ם בפרק ט' מהלכות יסודי התורה כי אם יבא נביא ויאמר לישראל על פי ה' לעבור על מצוה אחת הוראת שעה כאליהו בהר הכרמל וכדומה שומעין לו חוץ מעבודה זרה, והוא אומרו **ובני ישראל עשו** ולצד כי מעשה זה הוא מעשה בלתי הגון לגנוב דעת גוי, גם לגזול ממונם, ואיך יצדיקו ישראל לאומר להם עבור עבירה לזה אמר על פי משה פירוש אשר הובחן לנביא ובפרט זה יאמנו דבריו כנזכר:
@75 **וישאילום וינצלו וגו'**. פירוש לצד שנתן ה' חן העם בעיני המצרים ובזה היו המצרים משאילים אותם בעל כרחם ומחמת זה הצדיקו הדברים כי אין כוונתם ללכת בהחלט שאם כן היו מבקשים הם לקחת מהם להרויח יותר ובזה וינצלו את מצרים. והנה המשכיל על דבר יראה כי פועל אדם ישולם לו (ברכות ט:) כי לצד שישראל חבבו דבר היציאה ולא חששו להנאת ממון הוא הדבר והוא הסיבה שהפליאו להרויח וזכותם עומדת להם:
@78 **מצות כי לא חמץ**. פירוש הטעם שאפוהו מצות כי לא הותר להם לאכול חמץ לזה מהרו לאפותו מצה. והגם ששהה מעת לישה עד עת אפיה זמן מה. אולי כי היו מתעמלים בו, ולזה אמר הכתוב משארותם צרורות בשמלותם על שכמם, וכי לא היה להם מקום לשאת אותם שהוצרכו לתתם על שכמם, אלא כדי שיתעמלו בהם וכל זמן שמתעמלים בעיסה אינה מחמצת נוסף על שלא נתנו בו שאור לחמץ. ונתן הכתוב טעם **כי לא חמץ כי גורשו ממצרים** וגו':
@80 **ויהי מקץ וגו'**. ולא אמר הכתוב מה היה, ואם נתכוין על היציאה הרי חזר ואמר פעם ב' ויהי בעצם. עוד צריך לדעת מה צער ירמוז בתיבת **ויהי**. ואולי כי יגיד הכתוב הצער של עכובם עד הקץ ולא היה בהם זכות לצאת קודם הקץ. או לרמוז כי הצער שהיה לישראל במספר המוזכר למעלה דכתיב ומושב בני ישראל וגו' לא כל הזמן ההוא אלא מקץ:
@80 **ויהי בעצם**. רמז הצער של יציאת היוצאים עמהם שמהם סבבו רעות. או לרמוז כי לא חדלו המכות והצרות ממצרים גם בעצם היום הזה, וכן הוא אומר (במדבר ל''ג) ומצרים מקברים וגו' ובני ישראל יוצאים ביד רמה (י''ד ח'):
@81 **ליל שמורים וגו'**. יכוין הכתוב לרמוז ה' נסים מופלאים שזמנם לילה זו. א, בימי אברהם כשהכה את ד' מלכים (לר יד טו) ויחלק עליהם לילה. ב, ביציאת מצרים דכתיב (פסוק כט) ויהי בחצי הלילה. ג, בימי חזקיה כשהכה גבריאל מחנה סנחריב דכתיב (מ''ב י''ט) ויהי בלילה ההוא. ד, בימי מרדכי ואסתר (אסתד ו) בלילה ההוא נדדה שנת המלך. ה, גאולה העתידה. כנגד נס אברהם אמר **ליל שמורים הוא לה'** כי באמצעות הנס נתגלית אמתתו יתברך כאומרם ז''ל (בראשית רבה פמ''ב) שיש מהאומות שלא היו מאמינים בנס הצלתו מאור כשדים והאמינו בנם הכאת ד' מלכים. וכנגד מצרים אמר **להוציאם מארץ מצרים**. וכנגד נס חזקיהו אמר **הוא הלילה** הידוע לכם כרשום בדברי נביא (מ''ב י''ט) ויהי בלילה ההוא ויצא מלאך וגו'. וכנגד נס מרדכי אמר **הזה לה'**, וכנגד גאולה העתידה אמר **שמורים לכל בני ישראל לדורותם** פירושו לסוף הדורות בעגלא ובזמן קריב:
@82 **ויאמר ה' וגו' זאת חקת הפסח**. קשה למה לא אמר דבר אל בני ישראל כסדר האמור בכל מצוה ומצוה. ולפי מה שכתבנו (לעיל פסוק ג) כי פרשה זו נאמרה בי''ד בניסן לא הוצרך לומר דבר כי היא סמוכה עם דברו אל כל עדת ישראל שאמר שם. ויש לתת טעם למה לא נכתבה במקומה. כי לצד שמצוה זו בשלימות ישנה כפסח דורות נאמרה אחר יציאת מצרים לומר כי כל זה בשלימות מעכב לדורות:
@82 **וראיתי** מדרש רבותינו (שמות דבה פי''ט) שהוציא ה' רוח''מגן עדן ובשם פסחו של משה ונתקבצו כל ישראל ואמרו לו משה רבינו בבקשה האכילנו מפסח שלך אמר להם אם אין אתם נימולים אין אתם אוכלים דכתיב זאת חקת הפסח וגו' מיד נתנו עצמן ומלו וכו' עד כאן. הנה לפי מדרש זה לא קשה למה לא אמר דבר וגו' או לאמר כי פרשה זו למשה ולאהרן נאמרה וצוה אותם כל בן נכר וגו' ואחר שבאו ישראל לצד אכילת פסחו של משה המבושם מלו עצמם:
@82 **וקשה** לדברי המדרש איך יכול ליתן להם מפסחו והלא אין הפסח נאכל אלא למנוייו. ואולי שאמר להם כן כדי שימולו וכשימולו יהיה כמו כן פסחיהם כפסחו של משה מבושם. וראיתי ראיה לדברי המדרש שלא רצו למול ממה שאמר ביחזקאל (כ') וימרו בי ולא אבו לשמוע אלי וגו' ואומר לשפוך חמתי עליהם בתוך ארץ מצרים, הרי שלא קבלו עשות מצותיו יתברך:
@87 **וכי יגור אתך גר**. כאן הסכים על קבלת גרים מהערב רב כדעת משה. והוא אומרו **אתך**. עוד רמז דעת עליון כי לא הסכימה על הדבר אלא לרצון משה ה' חפץ כאומרם ז''ל (שמות רבה פמ''ב). והוא אומרו **אתך גר** פירוש עמך הוא גר שאין אתה בקי בנסתרות ולא מחשבותי מחשבותיכם, וצא ולמד מה עלתה בידם מהם:
@87 **המול לו כל זכר**. פירוש כשם שמילת עבד מעכבת בישראל שלא יאכל גם הגר מילת עבדיו וגו' מעכבת אותו עד שימול לו כל זכר. ואומרו **ואז יקרב** וגו'. פירוש לא יצטרך שישחטו אחרים עליו אלא הוא בעצמו יקרב לעשותו **והיה כאזרח** וגו':
@90 **ויהי בעצם וגו'**. הודיע הדבר בסמוך לעשית פסח. לומר כי זה גורם גמר היציאה, כי זולת זה לא היה בידם מצוות לצאת כאומרם ז''ל (שם פי''ז) בפ' ואעבור עליך וגו':
@95 **והיה כי יביאך וגו'**. טעם שתלה מצוה זו בביאת הארץ, לטעם עצמו שכתבנו בפסוק (לעיל י''ב כ''ה) והיה כי תבואו אל הארץ, או כדי שלא ישכח באורך הימים שם כשירבו ימיהם על האדמה:
@98 **והגדת לבנך וגו'**. צריך לדעת למה לא אמר ואמרת כי תיבת הגדה מצינו לרבותינו ז''ל שאמרו (שבת פ''ז.) שיתכוין בה דברים קשים כגידים. עוד קשה אומרו **ביום ההוא** ובסמוך גמר אומר בעבור זה ודרשו רבותינו ז''ל (מכילתא ובהגדה) בשעה שמצה ומרור וגו' והוא בלילה ולא ביום ואם כן לא היה לו לומר אלא ובגדת לבנך לאמר בעבור זה ואני יודע זמן ההגדה שהוא בלילה. עוד צריך לדעת אומרו **לאמר** והוא כבר אמר והגדת:
@98 **ונראה** כי יכוין על דרך אומרם ז''ל (פסחים קט''ז:) מתחיל בגנות ומסיים בשבח, יאמר גנות אבותיהם של האבות כי לא היה דבר משובח, והוא אומרו **והגדת** דברים קשים שלב האדם נעקש מהם, ואחר כך מסיים בשבח, והוא אומרו **לאמר** אמירות משובחות משמחים את הלב ומסעדים אותו, ואמר **ביום ההוא** הודיע במתק לשון צדיק כי הלילה ההוא יום יקרא לא לילה והוא אומרו (תהלים קל''ט) ולילה כיום יאיר, ולא חש שתטעה לומר יום ממש ממה שגמר אומר בעבור זה שהוא בשעת מצה כו' כאומרם ז''ל. ואולי כי סמך ביום ההוא עם והגדת כי גם נס זה בכלל מצות ההגדה:
@98 **עוד** ירצה באומרו **לאמר** להיות שאמר והגדת לבנך תינח אם יש לו בן אם אין לו בן יהיה פטור תלמוד לומר לאמר שעל כל פנים צריך להגיד אפילו בינו לבין עמו. ואם תאמר כיון שעל כל פנים הוא צריך להגיד אפילו בינו לבין עצמו אם כן למה אמר לבנך. ואולי שבאמצעות היתור אני מבין כן ולא בלא יתור. ואפשר עוד שירמוז באומרו **והגדת לבנך** שאם יגיד הגדה האמורה בנין יזכהו ה' שיגיד לבנו וכדי שלא תטעה לומר דוקא, לזה אמר לאמר:
@98 **בעבור זה**. אולי שרמז בתיבת זה י''ב מצות הרשומים בחג הפסח, ג' דברים פסח מצה ומרור, והגדה, וז' ימי החג, וקידוש יום א' וב', הרי י''ב כמספר ז''ה, והוא אומרו **בעבור זה עשה** וגו', והגם שז' ימי החג לענין תרי''ג מצות אינם נמנים לז' מצות:
@101 **והיה כי יביאך וגו'**. אמר **והיה כי יביאך** וגו' לומר שלא ישכח מצות ה' כי ירחיב ה' גבולו וישמן ויבעט, ולא חש לומר כי דוקא בארץ, לצד שהיא מצוה התלויה בגוף ואמרינן בקדושין (ל''ו:) שכל מצוה שהיא תלויה בגוף אין חילוק בין בארץ בין בחו''ל:
@104 **והיה כי ישאלך** וגו'. פירוש בשעה שיראה בנך ענין פדיון בכור אם ישאלך אתה חייב לומר לו אבל בלא שאלה אין חיוב אלא בליל פסח. ולזה דקדק לומר **מחר** פירוש אפילו למחר דהיינו כל זמן שיהיה, ואמר **לאמר** פירוש שתהיה כוונתו בשאלה שתאמר אליו אז הוא שתשיבהו בדרך האמור, אבל אם יאמר מה זאת בדרך זלזול לא לכוונת התשובה לא תשיבהו כזה:
@104 **עוד** ירצה שאין צריך שתהיה השאלה בלשון זה מה זאת אלא הגם שתהיה באיזה אופן שתהיה כל שהמכוון של השאלה הוא לאמר מה זאת, נמצינו אומרים כי פסוק זה שלא בליל פסח נאמר אלא במצות קדושת פטר רחם ואין צורך בהגדה זולת על ידי שאלה, ורבותינו ז''ל (מכילתא) אמרו כנגד ד' בנים כו' זה דרך דרוש:
@106 **והיה לאות על ידכה וגו'**. רבותינו ז''ל (מנחות ל''ז) אמרו ידכה יד כהה שהוא יד שמאל, וצריך לדעת מדוע לא בחר ה' ביד ימין לעשות בו המצוה כי הוא המשובח, ורבותינו אמרו (שם) להיותו מכוון כנגד הלב שבצד שמאל, ודבריהם אמת, אלא שנראה לי לתת טוב טעם כי הכתוב עצמו נתן טעם הדבר במה שכתב **כי בחוזק יד**, כי יש לך לדעת כי האדון ברוך הוא יש במדותיו ב' בחינות, הא' תקרא יד הגדולה, והא' תקרא יד החזקה, היד הגדולה היא צד החסד והטוב, והיד החזקה היא הגבורה המשלמת לעושה רעה כרעתו, והנה בהוצאת ישראל ממצרים נטה ה' יד החזקה והכה שונאיו עשר מכות, אשר לזה גמר אומר האדון שתהיה הנחת תפילין בכתיבת זכרון ביד כהה שלנו שהיא דוגמת יד החזקה המוציאה אותנו ממצרים, וזה שאמר הכתוב כאן **כי בחוז** ק **יד** ונכון. והגם שמצינו שאמר בהרבה פעמים יד הגדולה זו הסכמת מדת הרחמים למדת הדין אבל עיקר המשפט יד החזקה יתכנה:
@106 **חסלת פרשת בא**
